export const SECCIONES = [{"id": "gen", "n": "General", "d": "Principios fundamentales de roleplay"}, {"id": "ciu", "n": "Ciudadana", "d": "Vida cotidiana de los ciudadanos"}, {"id": "dep", "n": "Departamental", "d": "Policía, Ejército, EMS, Bomberos, DOT y negocios"}, {"id": "del", "n": "Delictiva", "d": "Actividades delictivas y organizaciones"}, {"id": "fin", "n": "Disposiciones finales", "d": "Autoridad de la normativa"}];
export const BLOQUES = {"A": "Departamentos primarios (Policía y Ejército)", "B": "Departamentos secundarios (EMS, Bomberos y DOT)", "C": "Negocios y locales civiles"};
export const ARTS = [{"id": "gen-1", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "1", "titulo": "El Roleplay debe ser siempre inmersivo", "tag": "", "intro": ["El Roleplay en esta comunidad debe ser siempre inmersivo.", "Todo participante se compromete a actuar y comportarse dentro del servidor como lo haría su personaje en el universo de Emergency Response: Liberty County, manteniendo en todo momento la coherencia con la realidad ficticia del juego."], "subs": [{"n": "1.1", "t": "Definición de Roleplay Inmersivo", "l": ["Se entiende por roleplay inmersivo aquel en el que:", "El jugador actúa exclusivamente como su personaje, dejando de lado su identidad real.", "Se mantiene una coherencia narrativa constante con el entorno, las leyes, los procedimientos y la lógica del mundo de Liberty County.", "Se evita cualquier elemento que rompa la suspensión de la incredulidad de los demás jugadores."]}, {"n": "1.2", "t": "Conductas que favorecen la inmersión", "l": ["Utilizar un lenguaje acorde al personaje (edad, profesión, personalidad y situación).", "Respetar los procedimientos policiales, médicos, civiles y legales propios del rol.", "Mantener acciones lógicas y realistas dentro del contexto (ejemplo: no correr a 200 km/h por la ciudad en un vehículo civil sin motivo justificado).", "Describir acciones con claridad cuando sea necesario (usando el chat cercano o /me).", "Resolver conflictos de forma natural y progresiva, dando oportunidad de interacción a los demás jugadores."]}, {"n": "1.3", "t": "Conductas que rompen la inmersión (Prohibidas)", "l": ["Hablar de temas fuera de personaje (OOC) en el chat de voz o cercano, salvo en casos excepcionales y usando el canal correspondiente.", "Realizar acciones imposibles o ilógicas (ej: saltar desde un helicóptero sin paracaídas y sobrevivir, o revivir mágicamente).", "Usar conocimiento que el personaje no posee (metagaming).", "Abusar de mecánicas del juego de forma no realista (powergaming).", "Romper el rol para hacer bromas, memes o comportamientos tóxicos fuera de contexto."]}, {"n": "1.4", "t": "Excepciones", "l": ["Solo se permiten breves comentarios OOC cuando sea estrictamente necesario para resolver problemas técnicos o de coordinación, y siempre deben hacerse de forma clara y mínima (preferiblemente en el chat de Discord o usando “-/OOC” en el juego)."]}]}, {"id": "gen-2", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "2", "titulo": "In Character (IC) vs Out of Character (OOC)", "tag": "", "intro": ["La correcta separación entre In Character (IC) y Out of Character (OOC) es fundamental para mantener la inmersión y el buen funcionamiento de la comunidad. Todo miembro debe comprender y respetar esta distinción en todo momento."], "subs": [{"n": "2.1", "t": "Definiciones", "l": ["In Character (IC): Todo lo que hace, dice, sabe o siente el personaje dentro del universo de Liberty County. Incluye acciones, diálogos, decisiones, emociones y conocimiento que el personaje ha adquirido durante su rol.", "Out of Character (OOC): Todo lo relacionado con el jugador real fuera del rol. Incluye opiniones personales, información del mundo real, problemas técnicos, bromas fuera de contexto, coordinaciones administrativas, etc."]}, {"n": "2.2", "t": "Principios Generales", "l": ["Separación Obligatoria: Nunca se debe mezclar información, acciones o conflictos IC con OOC, ni viceversa.", "Respeto a la Cuarta Pared: El jugador debe actuar como si su personaje no tuviera conocimiento de que está dentro de un juego.", "No llevar conflictos OOC al IC ni conflictos IC al OOC (revenge, hate, etc.)."]}, {"n": "2.3", "t": "Normas Específicas", "l": ["Está permitido y recomendado:", "Usar el formato -/OOC en el chat del juego para comentarios breves fuera de rol.", "Utilizar canales específicos de Discord marcados como OOC para coordinaciones, reportes o conversaciones personales.", "Hablar OOC en voz solo cuando sea necesario y siempre de forma breve y clara.", "Está estrictamente prohibido:", "Hablar OOC en canales IC (chat cercano, voz cercana, radio policial, etc.) sin usar el formato adecuado.", "Usar información OOC en beneficio del personaje (Metagaming). Ejemplos:", "Usar el nombre real de un jugador que no ha sido revelado IC.", "Conocer ubicaciones o hechos que el personaje no ha presenciado.", "Usar Discord para coordinar acciones delictivas o policiales en lugar de hacerlo dentro del rol.", "Llevar rencores, venganzas o toxicidad del IC al OOC (o viceversa).", "Revelar información sensible OOC dentro del rol (ej: “te estoy grabando”, “esto es un stream”, “soy amigo del admin”, etc.).", "Interrumpir escenas de roleplay con comentarios OOC innecesarios."]}, {"n": "2.4", "t": "Excepciones", "l": ["Se permite la comunicación OOC en los siguientes casos:", "Problemas técnicos graves que impidan continuar el roleplay.", "Necesidad de coordinación urgente con el Staff.", "Reporte de infracciones graves (debe hacerse preferiblemente por ticket o canal privado).", "En estos casos, la comunicación debe ser clara, breve y respetuosa, y se debe volver al IC tan pronto como sea posible."]}]}, {"id": "gen-3", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "3", "titulo": "Metagaming (MG)", "tag": "Prohibido estrictamente", "intro": ["El Metagaming es una de las infracciones más graves contra la inmersión en el roleplay. Consiste en utilizar información obtenida fuera de personaje (OOC) para beneficiar o influir en las acciones del personaje (IC)."], "subs": [{"n": "3.1", "t": "Definición", "l": ["Se considera Metagaming cualquier acción en la que el jugador hace que su personaje actúe basándose en conocimiento que este no ha adquirido de forma legítima dentro del rol."]}, {"n": "3.2", "t": "Ejemplos de Metagaming (Prohibidos)", "l": ["Usar el nombre real o apodo OOC de otro jugador cuando el personaje no lo conoce.", "Conocer la ubicación exacta de una persona o vehículo sin haberla visto o recibido información IC (ej. mirar el mapa de Discord o streams).", "Saber que alguien es policía, criminal, médico, etc., sin haberlo descubierto dentro del roleplay.", "Utilizar información de conversaciones de Discord, Teamspeak u otros canales OOC para tomar decisiones IC.", "Seguir o perseguir a un jugador porque sabes que está cometiendo un delito en otro servidor o en un stream, sin haberlo presenciado IC.", "Recordar rostros o placas de vehículos de sesiones anteriores sin justificación IC.", "Usar la lista de jugadores en línea para saber quién está conectado y actuar en consecuencia."]}, {"n": "3.3", "t": "Principios Generales", "l": ["Tu personaje solo puede actuar con la información que ha obtenido dentro del universo del juego a través de sus sentidos y experiencias.", "El conocimiento del jugador y el conocimiento del personaje deben estar separados.", "Toda información relevante debe transmitirse dentro del roleplay (radio, conversación presencial, notas, etc.)."]}, {"n": "3.4", "t": "Conductas Recomendadas", "l": ["Si necesitas información, obténla de forma natural dentro del rol.", "Si no estás seguro de si algo es metagaming, pregúntale al Staff antes de actuar.", "Cuando recibas información IC, actúa de forma coherente con la personalidad y situación de tu personaje."]}, {"n": "3.5", "t": "Sanciones", "l": ["El Metagaming se considera una falta grave. Dependiendo de la intención y el impacto en otros jugadores, podrá ser sancionado desde una amonestación hasta la expulsión temporal o definitiva de la comunidad."]}]}, {"id": "gen-4", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "4", "titulo": "Powergaming (PG)", "tag": "Prohibido estrictamente", "intro": ["El Powergaming es el uso abusivo o irrealista de las mecánicas del juego. Consiste en forzar situaciones o acciones que rompen la inmersión y perjudican el roleplay de los demás."], "subs": [{"n": "4.1", "t": "Definición", "l": ["Se considera Powergaming cualquier acción que otorga ventajas irreales al personaje o impone resultados sobre otros jugadores sin darles oportunidad de responder de forma coherente."]}, {"n": "4.2", "t": "Ejemplos Prohibidos", "l": ["Realizar acciones imposibles o invencibles (godmoding).", "Forzar detenciones, golpes o muertes sin permitir reacción del otro jugador.", "Abusar de vehículos o armas de forma irrealista (velocidades extremas constantes, maniobras imposibles).", "Ignorar heridas graves o consecuencias lógicas de las acciones."]}, {"n": "4.3", "t": "Principios Generales", "l": ["Todas las acciones deben ser lógicas y realistas dentro del contexto del juego.", "Se debe dar oportunidad de respuesta en situaciones de conflicto.", "El roleplay tiene prioridad sobre “ganar” una escena."]}, {"n": "4.4", "t": "Sanciones", "l": ["El Powergaming es una falta grave. Las sanciones pueden ir desde una advertencia hasta la expulsión temporal o definitiva, según la gravedad y reiteración."]}]}, {"id": "gen-5", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "5", "titulo": "Fail Roleplay (FailRP)", "tag": "Prohibido", "intro": ["El Fail Roleplay (FailRP) ocurre cuando un jugador realiza acciones que rompen gravemente la lógica, el sentido común o la inmersión del roleplay."], "subs": [{"n": "5.1", "t": "Definición", "l": ["Se considera FailRP cualquier comportamiento que no encaja con la realidad del universo de Liberty County o que daña la experiencia inmersiva de los demás jugadores."]}, {"n": "5.2", "t": "Ejemplos Prohibidos", "l": ["Realizar acciones ilógicas o absurdas (ej: conducir en contramano a alta velocidad sin motivo, robar un banco solo o atacar a un grupo de policías armado con un cuchillo).", "Ignorar completamente el contexto de la situación (ej: continuar roleando normalmente después de un accidente grave sin buscar ayuda médica).", "Comportamientos que no corresponden al personaje (un civil actuando como un SWAT entrenado).", "Romper escenas importantes con bromas o acciones fuera de contexto.", "Revivir o continuar actuando después de una muerte sin justificación RP."]}, {"n": "5.3", "t": "Principios Generales", "l": ["Todas las acciones deben ser coherentes, lógicas y realistas.", "El jugador debe actuar siempre según lo que haría su personaje en esa situación."]}, {"n": "5.4", "t": "Sanciones", "l": ["El FailRP es una falta grave. Las sanciones pueden ir desde una advertencia hasta la expulsión temporal o definitiva, dependiendo de la gravedad y la reiteración."]}]}, {"id": "gen-6", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "6", "titulo": "Random Deathmatch (RDM)", "tag": "Prohibido", "intro": ["El Random Deathmatch (RDM) consiste en matar o atacar a otros jugadores sin ninguna razón válida de roleplay."], "subs": [{"n": "6.1", "t": "Definición", "l": ["Se considera RDM cualquier acto de violencia (disparos, golpes, atropellos, explosiones, etc.) realizado sin justificación previa dentro del roleplay o sin interacción coherente con la víctima."]}, {"n": "6.2", "t": "Ejemplos Prohibidos", "l": ["Matar a un jugador al azar sin motivo RP.", "Atacar a alguien solo porque te miró, te siguió o te cayó mal.", "Iniciar tiroteos sin razón de rol (robos, venganzas, detenciones, etc.).", "Atropellar personas sin motivo justificado.", "Matar por venganza OOC o por frustración personal."]}, {"n": "6.3", "t": "Principios Generales", "l": ["Toda acción violenta debe tener una razón lógica y coherente dentro del roleplay.", "Se debe priorizar la interacción y el desarrollo de la escena antes de recurrir a la violencia.", "Los conflictos deben escalar de forma natural y progresiva."]}, {"n": "6.4", "t": "Sanciones", "l": ["El RDM es una falta grave. Las sanciones pueden ir desde una advertencia hasta la expulsión temporal o definitiva, dependiendo de la gravedad, el número de víctimas y la reiteración."]}]}, {"id": "gen-7", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "7", "titulo": "Vehicle Deathmatch (VDM)", "tag": "Prohibido", "intro": ["El Vehicle Deathmatch (VDM) consiste en usar vehículos de forma intencionada para dañar, atropellar o matar a otros jugadores sin justificación de roleplay."], "subs": [{"n": "7.1", "t": "Definición", "l": ["Se considera VDM cualquier uso de un vehículo como arma para atacar o matar sin motivo válido dentro del roleplay."]}, {"n": "7.2", "t": "Ejemplos Prohibidos", "l": ["Atropellar intencionalmente a jugadores sin razón RP.", "Usar vehículos para embestir o bloquear de forma agresiva sin contexto.", "Intentar matar o herir a alguien conduciendo de manera suicida o kamikaze.", "Perseguir y atropellar repetidamente a un jugador sin motivo de rol.", "Usar helicópteros o barcos para impactar contra personas sin justificación."]}, {"n": "7.3", "t": "Principios Generales", "l": ["Los vehículos deben usarse de forma realista y coherente con el roleplay.", "Toda acción con vehículos debe tener una razón lógica dentro de la escena.", "Se prioriza la seguridad vial y el respeto a los peatones dentro del rol."]}, {"n": "7.4", "t": "Sanciones", "l": ["El VDM es una falta grave. Las sanciones pueden ir desde una advertencia hasta la expulsión temporal o definitiva, según la gravedad, el número de víctimas y la reiteración."]}]}, {"id": "gen-8", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "8", "titulo": "Avatar Realista", "tag": "", "intro": ["El avatar del jugador debe mantener un aspecto realista y acorde."], "subs": [{"n": "8.1", "t": "Definición", "l": ["Se entiende por avatar realista aquel que representa de forma creíble a un ser humano dentro del contexto realista del servidor."]}, {"n": "8.2", "t": "Requisitos Obligatorios", "l": ["El avatar debe tener proporciones cuadradas (hombres). Para mujeres no es necesario el cuerpo cuadrado pero debe de tener proporciones realistas.", "Se permite ropa civil, ropa de gala, médica o laboral acorde al rol.", "No se permiten caras o cuerpos exagerados, meme, anime, animales o personajes fantásticos.", "La ropa no debe ser extremadamente provocativa, obscena o inapropiada.", "El avatar debe ser visible y no puede usar accesorios que oculten completamente el rostro sin motivo RP.", "El avatar no puede llevar accesorios tacticos o militares."]}, {"n": "8.3", "t": "Principios Generales", "l": ["El avatar es la representación visual de tu personaje.", "Debe ayudar a mantener la inmersión y no distraer o romper el roleplay de los demás.", "Los cambios de avatar deben ser coherentes con la historia de tu personaje."]}, {"n": "8.4", "t": "Sanciones", "l": ["El uso de avatar no realista es una falta media. Se dará un tiempo para corregirlo. La reiteración puede conllevar sanciones más graves, hasta expulsión temporal."]}]}, {"id": "gen-9", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "9", "titulo": "Forzar Roleplay", "tag": "Prohibido", "intro": ["El Forzar Roleplay consiste en imponer acciones, situaciones o interacciones a otros jugadores sin su consentimiento o sin darles oportunidad de participar de forma natural."], "subs": [{"n": "9.1", "t": "Definición", "l": ["Se considera Forzar Roleplay cualquier intento de obligar a otro jugador a entrar en una escena de rol en contra de su voluntad o sin una interacción lógica previa."]}, {"n": "9.2", "t": "Ejemplos Prohibidos", "l": ["Secuestrar o detener a un jugador sin motivo RP previo ni interacción.", "Iniciar un roleplay romántico, sexual o violento sin consentimiento del otro jugador.", "Forzar a alguien a seguir una escena cuando claramente está intentando evitarla o salir de ella.", "Imponer resultados o acciones sobre otros personajes sin darles oportunidad de responder.", "Continuar una escena cuando el otro jugador ha indicado OOC que no desea participar."]}, {"n": "9.3", "t": "Principios Generales", "l": ["El roleplay debe ser consentido y cooperativo.", "Se debe respetar la voluntad de los demás jugadores en todo momento.", "Toda interacción importante debe desarrollarse de forma natural y progresiva."]}, {"n": "9.4", "t": "Sanciones", "l": ["Forzar Roleplay es una falta grave. Las sanciones pueden ir desde una advertencia hasta la expulsión temporal o definitiva, según la gravedad y la reiteración."]}]}, {"id": "gen-10", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "10", "titulo": "Evadir Roleplay", "tag": "Prohibido", "intro": ["El Evadir Roleplay consiste en evitar intencionalmente las consecuencias o interacciones lógicas del roleplay."], "subs": [{"n": "10.1", "t": "Definición", "l": ["Se considera Evadir Roleplay cualquier acción que busca esquivar la responsabilidad, los procedimientos o las interacciones obligatorias dentro del rol."]}, {"n": "10.2", "t": "Ejemplos Prohibidos", "l": ["No portar el Documento Nacional de Identidad (DNI) sin justificación RP. Se permite solo si el jugador presenta grabaciones que demuestren que lo dejó en casa u otro lugar como acción previa de rol.", "No proporcionar la información correcta de tu personaje mediante el comando /do durante un procedimiento policial con la intención de registrar datos falsos.", "Huir o desconectarse para evitar consecuencias RP.", "Negarse a interactuar en escenas obligatorias (robos, detenciones, etc.).", "Fingir no entender o no escuchar para evitar el desarrollo del roleplay.", "Es imposible realizar llamadas !mod para parar roles activos."]}, {"n": "10.3", "t": "Principios Generales", "l": ["Todo jugador debe aceptar las consecuencias lógicas de sus acciones dentro del roleplay.", "La cooperación es esencial para mantener una experiencia justa e inmersiva."]}, {"n": "10.4", "t": "Sanciones", "l": ["Evadir Roleplay es una falta grave. Las sanciones pueden ir desde una advertencia hasta la expulsión temporal o definitiva, según la gravedad y la reiteración."]}]}, {"id": "gen-11", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "11", "titulo": "Realismo Vehicular (Bad Driving – BD) - (Anexo: Uso del Vehiculo)", "tag": "", "intro": ["La Conducción Realista exige que todos los vehículos se conduzcan de forma coherente y segura dentro del universo de Liberty County."], "subs": [{"n": "11.1", "t": "Definición", "l": ["Se considera Bad Driving (BD) cualquier forma de conducción irrealista, peligrosa o que rompa la inmersión, sin justificación de roleplay."]}, {"n": "11.2", "t": "Ejemplos Prohibidos", "l": ["Conducir a velocidades extremas de forma constante en zonas urbanas sin motivo RP.", "Conducir con un vehiculo sedan, coupe, deportivo o que no cumpla con requisitos 4x4 (todoterreno) por caminos rocosos o elevaciones de tierra que no son aptos para vehiculos regulares.", "Realizar maniobras imposibles o acrobáticas (derrapes excesivos, saltos, giros de 180° sin control).", "Ignorar completamente las normas de tránsito de manera habitual (semáforos, stop, carriles, etc.).", "Conducir en contramano, por aceras o fuera de la carretera sin motivo justificado.", "Usar vehículos para bloquear caminos o rampear de forma constante.", "Conducir en reversa durante distancias largas o a alta velocidad."]}, {"n": "11.3", "t": "Principios Generales", "l": ["Los vehículos deben conducirse como lo haría una persona normal en la vida real.", "Se permite conducción agresiva solo cuando tenga una razón válida de roleplay (persecuciones, emergencias, etc.).", "La seguridad y el realismo tienen prioridad."]}, {"n": "", "t": "ANEXO: USO DEL VEHICULO", "l": []}, {"n": "11.4", "t": "Normas Adicionales sobre Vehículos", "l": ["No podra descender del vehiculo a mas de 20 KPH / 10 MPH. Fuerzas especiales policiales entrenados solo podran descender del vehiculo en un rango de 20-60 KPH / 10-40 MPH.", "Las placas vehiculares deben seguir el formato realista AAA-###. Para autos sin placa se debe de rolear la accion de retirar la placa.", "Las placas vehiculares no pueden tener nombres o siglas que invoquen ofensas.", "El blindaje vehicular está estrictamente prohibido.", "Molestar a otros jugadores cerrandoles el paso o bugeando el vehiculo", "Los colores de los vehículos no pueden ser irrealistas o extremadamente chillones.", "El robo de vehículos oficiales (Policía, EMS y Bomberos) está prohibido.", "El uso de vehículos eléctricos está reservado exclusivamente para miembros con membresía activa.", "Restricciones durante persecuciones:", "Durante persecuciones policiales se presentan diversos problemas que son inevitables en el universo de ER:LC, por esto mismo se dictan las siguientes restricciones:", "Durante codigos PIT el civil conductor debe entender y reconocer que su vehiculo por cada pit pierde \"vida util\". por lo que ir a altas velocidades luego de 4 codigos pit es considerado irrealista.", "Si su vehiculo luego de un codigo PIT colisiona fuertemente con algun objeto inmovil, otro vehiculo o patrulla debe de considerar que ya no podra seguir conduciendolo.", "Si su vehiculo se prende fuego por causa de un codigo PIT debe considerar que usted queda sin el derecho de rolear heridas por quemadura buscando atrasar o interrumpir el rol."]}, {"n": "11.5", "t": "Sanciones", "l": ["El Bad Driving es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal, dependiendo de la peligrosidad, el daño causado y la reiteración. Las infracciones a las normas adicionales de vehículos también aplican estas sanciones."]}]}, {"id": "gen-12", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "12", "titulo": "Uso Correcto de /me y /do", "tag": "Importante", "intro": ["/me: describe acciones físicas visibles o no visibles del personaje.", "/do: describe entorno, estados o situaciones externas. Prohibido usarlos para mentir, forzar resultados o alterar la realidad de la escena."], "subs": []}, {"id": "gen-13", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "13", "titulo": "Roleo de Acciones No Visibles", "tag": "Importante", "intro": ["El Roleo de Acciones No Visibles es obligatorio para mantener la inmersión en acciones que el juego no muestra de forma automática."], "subs": [{"n": "13.1", "t": "Definición", "l": ["Se refiere a todas aquellas acciones que no son visibles para otros jugadores mediante animaciones o mecánicas del juego. Estas deben ser descritas correctamente usando comandos como /me o chat cercano."]}, {"n": "13.2", "t": "Ejemplos Obligatorios", "l": ["Buscar objetos en bolsillos, mochilas o vehículos.", "Sacar o guardar armas, dinero, drogas u objetos pequeños.", "Susurrar, hablar en voz baja o pasar información discretamente.", "Realizar acciones ocultas (revisar un documento, manipular algo bajo la mesa, etc.).", "Cualquier interacción que no sea evidente para los demás jugadores."]}, {"n": "13.3", "t": "Principios Generales", "l": ["Todas las acciones no visibles deben ser roleadas de forma clara y detallada.", "Esto permite que los demás jugadores puedan reaccionar de manera coherente.", "El uso correcto de /me y /do ayuda a mantener la inmersión y evita confusiones."]}, {"n": "13.4", "t": "Sanciones", "l": ["No rolear acciones no visibles es una falta media.", "La reiteración puede considerarse FailRP y aumentar la gravedad de la sanción."]}]}, {"id": "gen-14", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "14", "titulo": "PI / Rol de Interpretación (Character Consistency)", "tag": "Considera", "intro": ["El Rol de Interpretación exige que cada jugador mantenga la coherencia y personalidad de su personaje en todo momento."], "subs": [{"n": "14.1", "t": "Definición", "l": ["Se entiende por Character Consistency la obligación de actuar siempre según la historia, personalidad, edad, profesión y valores establecidos de tu personaje, sin cambios bruscos o incoherentes."]}, {"n": "14.2", "t": "Ejemplos Prohibidos", "l": ["Cambiar radicalmente la personalidad del personaje sin razón RP (ej: un criminal pacífico que de repente se vuelve extremadamente violento).", "Actuar de forma opuesta a la historia o background del personaje.", "Usar conocimiento o habilidades que no corresponden al personaje (un civil actuando como experto en tácticas SWAT).", "Olvidar eventos importantes ocurridos en el roleplay del personaje.", "Romper el carácter para hacer bromas o comportamientos que no encajan con su rol."]}, {"n": "14.3", "t": "Principios Generales", "l": ["Tu personaje debe ser consistente y creíble en todo momento.", "Los cambios en la personalidad o historia deben desarrollarse de forma progresiva y justificada dentro del roleplay.", "La interpretación de calidad es uno de los pilares del roleplay inmersivo."]}, {"n": "14.4", "t": "Sanciones", "l": ["La falta de consistencia en el personaje es una falta media.", "La reiteración o casos graves pueden considerarse FailRP y recibir sanciones más severas, hasta expulsión temporal."]}, {"n": "", "t": "ANEXO: (PI  - Provocación Innecesaria)", "l": ["Se considera provocación innecesaria cualquier acción, comentario o comportamiento cuyo único objetivo sea molestar, alterar o generar conflicto sin propósito RP válido."]}, {"n": "", "t": "Prohibiciones", "l": ["Provocar de forma repetitiva o gratuita a otros jugadores.", "Usar insultos, burlas o actitudes tóxicas fuera de un contexto RP justificado.", "Buscar conflicto solo por diversión o para generar drama OOC.", "Provocar a nuevos jugadores o a aquellos que claramente no desean interactuar."]}]}, {"id": "gen-15", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "15", "titulo": "No Valorar la Vida del Personaje (FearRP)", "tag": "Importante", "intro": ["El FearRP (Fear Roleplay) exige que los jugadores valoren la vida de su personaje de forma realista en situaciones de peligro."], "subs": [{"n": "15.1", "t": "Definición", "l": ["Se considera falta de FearRP actuar sin temor a la muerte o a sufrir graves consecuencias cuando la situación claramente lo justifica."]}, {"n": "15.2", "t": "Ejemplos Prohibidos", "l": ["No rendirse o huir cuando estás apuntado con un arma a corta distancia.", "Continuar atacando o resistiendo en situaciones donde la vida del personaje está en claro peligro.", "No mostrar miedo o preocupación ante amenazas creíbles (armas, superioridad numérica, etc.).", "Actuar de forma suicida o temeraria sin justificación de rol.", "Ignorar heridas graves y seguir combatiendo como si nada."]}, {"n": "15.3", "t": "Principios Generales", "l": ["Tu personaje debe valorar su vida de forma lógica y realista.", "En situaciones de alto riesgo, se debe priorizar la supervivencia y actuar con miedo o precaución.", "El FearRP ayuda a crear escenas más inmersivas y justas."]}, {"n": "15.4", "t": "Sanciones", "l": ["La falta de FearRP es una falta grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, según la gravedad, el impacto en otros jugadores y la reiteración."]}]}, {"id": "gen-16", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "16", "titulo": "Tiempo de Respawn", "tag": "Importante", "intro": ["El Tiempo de Respawn regula el período que debe esperar un jugador después de morir antes de volver a entrar en el servidor."], "subs": [{"n": "16.1", "t": "Definición", "l": ["Se establece un tiempo mínimo de espera tras la muerte del personaje para respetar las consecuencias de los eventos y evitar el regreso inmediato a la escena."]}, {"n": "16.2", "t": "Requisitos Obligatorios", "l": ["Debes esperar 5 minutos desde el momento en que la escena termina luego de tu muerte antes de volver a respawnear.", "Durante este tiempo no puedes volver a la escena nuevamente ni observar la escena.", "No puedes regresar al lugar donde moriste ni interactuar con los jugadores involucrados en el incidente (New Life Rule)."]}, {"n": "16.3", "t": "Principios Generales", "l": ["El tiempo de respawn permite que las escenas continúen de forma natural y respeta las consecuencias de las acciones.", "Tu personaje debe olvidar todo lo ocurrido en su vida anterior hasta el momento de la muerte."]}, {"n": "16.4", "t": "Sanciones", "l": ["Incumplir el tiempo de respawn o regresar antes de tiempo es una falta grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, dependiendo de la reiteración y el impacto causado."]}]}, {"id": "gen-17", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "17", "titulo": "Character Kill (CK)", "tag": "Considera", "intro": ["El Character Kill (CK) es la muerte permanente de un personaje dentro del servidor."], "subs": [{"n": "17.1", "t": "Definición", "l": ["Se considera Character Kill la eliminación definitiva de un personaje, lo que impide al jugador volver a usarlo en el servidor. Esta medida solo se aplica en casos excepcionales y justificados."]}, {"n": "17.2", "t": "Requisitos y Procedimiento", "l": ["El CK debe ser solicitado al Staff o aprobado por este.", "Solo se permite cuando la situación RP lo justifique de forma extrema (muerte confirmada y sin posibilidad de revivir).", "Requiere acuerdo entre las partes involucradas o decisión del Staff en casos graves.", "Tras un CK aprobado, el jugador deberá crear un nuevo personaje.", "Posterior a un CK el jugador debera tener una vida ciudadana regular durante 7 dias."]}, {"n": "17.3", "t": "Principios Generales", "l": ["El CK es una herramienta narrativa seria y no debe usarse de forma abusiva o por venganza.", "Debe respetarse siempre el FearRP y las consecuencias lógicas del roleplay.", "No es permitido utilizar el CK para evitar o saltarse normativas IC/OOC.", "No se permite utilizar el CK multiples veces (Mas de 2 veces en un mes).", "No se permite forzar un CK sin aprobación del Staff."]}, {"n": "17.4", "t": "Sanciones", "l": ["Realizar un CK sin autorización o abusar de esta mecánica es una falta grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva."]}]}, {"id": "gen-18", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "18", "titulo": "Zonas Seguras", "tag": "", "intro": ["Las Zonas Seguras son áreas específicas del servidor donde se prohíbe cualquier tipo de violencia o acción disruptiva para proteger la inmersión y la experiencia de los jugadores."], "subs": [{"n": "18.1", "t": "Definición", "l": ["Las Zonas Seguras son lugares designados donde no se permite combatir, robar, secuestrar, disparar, arrestar ni realizar acciones violentas o de alto riesgo. En caso que el rol haya iniciado fuera de alguna zona segura y por alguna situación se trasladan a alguna de estas el rol podrá continuar en esta."]}, {"n": "18.2", "t": "Zonas Seguras Principales", "l": ["Hospital y sus alrededores.", "Estacion de bomberos.", "Comisaría principal y dependencias policiales.", "Ayuntamiento y edificios gubernamentales.", "Spawn / Zona de llegada de nuevos jugadores.", "Otras zonas que el Staff marque explícitamente como seguras."]}, {"n": "18.3", "t": "Reglas en Zonas Seguras", "l": ["Está prohibido todo tipo de violencia (física, verbal agresiva o con armas).", "No se permiten robos, detenciones ni persecuciones dentro o cerca de estas zonas.", "Se debe mantener un roleplay calmado y respetuoso.", "No se permite entrar a zonas seguras con la intencion de huir de alguna escena.", "Se prohíbe en su totalidad el permanecer en las zonas seguras con la intención de seguir, perseguir o atacar a otros usuarios cuando dejen estas áreas."]}, {"n": "18.4", "t": "Sanciones", "l": ["Incumplir las reglas de Zonas Seguras es una falta grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, especialmente si afecta a nuevos jugadores o personal médico/policial."]}]}, {"id": "gen-19", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "19", "titulo": "Team Kill (TK)", "tag": "Importante", "intro": ["El Team Kill (TK) consiste en matar, herir o atacar intencionalmente a miembros de tu mismo equipo o facción sin justificación de roleplay."], "subs": [{"n": "19.1", "t": "Definición", "l": ["Se considera Team Kill cualquier acto de violencia (disparos, golpes, atropellos, explosiones, etc.) realizado contra compañeros de equipo, facción o aliados sin motivo válido dentro del roleplay."]}, {"n": "19.2", "t": "Ejemplos Prohibidos", "l": ["Disparar o golpear a un compañero policía, médico o de la misma banda sin razón RP.", "Atacar a miembros de tu facción por frustración, broma o error.", "Provocar daño accidental sin rolearlo ni asumir las consecuencias.", "Matar a aliados durante una operación coordinada sin justificación narrativa.", "Usar vehículos o armas contra tu propio equipo de forma intencionada."]}, {"n": "19.3", "t": "Principios Generales", "l": ["Se debe cuidar y proteger a los miembros de tu equipo o facción.", "Cualquier conflicto interno debe desarrollarse de forma coherente y justificada dentro del roleplay.", "Los errores accidentales deben rolearse y resolverse de manera madura."]}, {"n": "19.4", "t": "Sanciones", "l": ["El Team Kill es una falta grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, dependiendo de la intención, el daño causado y la reiteración."]}]}, {"id": "gen-20", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "20", "titulo": "Meta Kill (MK)", "tag": "Importante", "intro": ["El Meta Kill (MK) consiste en matar o atacar a otro jugador utilizando información obtenida fuera del roleplay (metagaming)."], "subs": [{"n": "20.1", "t": "Definición", "l": ["Se considera Meta Kill cualquier acto de violencia realizado contra un jugador basándose en conocimiento OOC (fuera de personaje) en lugar de información adquirida legítimamente dentro del roleplay."]}, {"n": "20.2", "t": "Ejemplos Prohibidos", "l": ["Matar a alguien porque viste su nombre o stream fuera del servidor.", "Atacar o emboscar a un jugador usando información de Discord, amigos o listas de jugadores.", "Localizar y matar a una persona basándote en su ubicación OOC o en sesiones anteriores.", "Vengar una muerte anterior usando conocimiento de otra sesión o servidor.", "Matar a alguien solo porque sabes que es enemigo en la vida real o en otro contexto OOC."]}, {"n": "20.3", "t": "Principios Generales", "l": ["Toda acción violenta debe basarse exclusivamente en información obtenida dentro del roleplay.", "El conocimiento del jugador y el conocimiento del personaje deben permanecer completamente separados.", "Cualquier muerte debe tener una justificación clara y lógica dentro de la narrativa."]}, {"n": "20.4", "t": "Sanciones", "l": ["El Meta Kill es una falta muy grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, dependiendo de la intención y el impacto en la comunidad."]}]}, {"id": "gen-21", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "21", "titulo": "Entornos / No Rolear Entorno (NRE)", "tag": "", "intro": ["El No Rolear Entorno (NRE) ocurre cuando un jugador ignora o no interactúa con el entorno que le rodea de forma realista."], "subs": [{"n": "21.1", "t": "Definición", "l": ["Se considera NRE no describir ni reaccionar de manera coherente ante elementos del entorno, clima, objetos, edificios o situaciones que afectan directamente al roleplay."]}, {"n": "21.2", "t": "Ejemplos Prohibidos", "l": ["Ignorar la lluvia, la nieve o condiciones climáticas extremas (no usar ropa adecuada, no correr a cubierto, etc.).", "No rolear correctamente el interior de un edificio, vehículo o zona (ej: entrar a un banco sin describir acciones lógicas).", "Ignorar barricadas, puertas cerradas, luces apagadas u obstáculos del entorno.", "No interactuar con objetos del escenario (sillas, mesas, computadoras, etc.) cuando la escena lo requiere.", "Actuar como si el entorno no existiera en situaciones de alto riesgo (ej: esconderse detrás de una pared inexistente)."]}, {"n": "21.3", "t": "Principios Generales", "l": ["El jugador debe observar e interactuar con el entorno de forma inmersiva.", "Usar comandos como /me o /do ayuda a describir cómo el personaje percibe y reacciona al entorno.", "Esto enriquece la escena y permite que otros jugadores respondan de manera coherente.", "Falsificación de entorno: Está prohibido redactar entornos falsos o manipularlos con el fin de obtener beneficios o desinformar a la policía. Esto será considerado una falta grave y conlleva a una sanción severa."]}, {"n": "21.4", "t": "Sanciones", "l": ["El No Rolear Entorno es una falta media. La reiteración puede considerarse FailRP y aumentar la gravedad de la sanción."]}]}, {"id": "gen-22", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "22", "titulo": "Roleo de Heridas / No Rolear Heridas (NRH)", "tag": "Importante", "intro": ["El Roleo de Heridas obliga a los jugadores a interpretar de forma realista cualquier lesión recibida durante el roleplay."], "subs": [{"n": "22.1", "t": "Definición", "l": ["Se considera No Rolear Heridas (NRH) actuar como si no hubiera recibido daño alguno después de sufrir heridas graves (disparos, golpes, accidentes, etc.)."]}, {"n": "22.2", "t": "Ejemplos Prohibidos", "l": ["Recibir varios disparos y continuar corriendo o combatiendo normalmente.", "Ignorar heridas visibles (sangrado, fracturas, inconsciencia) y seguir roleando sin consecuencias.", "Negarse a recibir atención médica después de una lesión grave.", "Recuperarse de heridas serias en pocos minutos sin justificación RP.", "No cojear, no mostrar dolor o no actuar debilitado tras recibir daño.", "Autolesiones o suicidio: Realizar autolesiones o actos suicidas sin un desarrollo RP profundo, coherente y justificado. Estas acciones deben ser roleadas con seriedad y realismo.", "Comunicación en estado de inconsciencia: Hablar, gritar o transmitir información mientras el personaje está inconsciente o gravemente herido.", "Realismo en rol de choque: No rolear correctamente los efectos de un accidente vehicular (latigazo cervical, conmoción, dolor, imposibilidad de moverse con normalidad).", "Se deberá permanecer un mínimo de 5 minutos en cama de hospital, como simulación del proceso médico de recuperación y estabilización del personaje.", "No rolear el uso correcto de chaleco antibalas (los chalecos reducen daño pero no lo eliminan por completo) (Debe ser visible el chaleco)."]}, {"n": "22.3", "t": "Principios Generales", "l": ["Todas las heridas deben ser roleadas de forma coherente y realista.", "El jugador debe actuar según la gravedad de la lesión recibida.", "En caso de ausencia total de personal EMS en servicio, los ciudadanos podrán trasladar a los personajes heridos hacia los puntos de atención hospitalaria disponibles dentro del rol.", "Durante el traslado, el jugador herido no podrá realizar ninguna acción hasta que se encuentre correctamente acostado en una cama de hospital.", "Se recomienda usar comandos /me o /do para describir el estado de las heridas."]}, {"n": "22.4", "t": "Sanciones", "l": ["El No Rolear Heridas (NRH) es una falta grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, dependiendo de la gravedad y la reiteración."]}]}, {"id": "gen-23", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "23", "titulo": "BunnyJump (BJ) / ZigZag Abuse (ZZA)", "tag": "Prohibido", "intro": ["El ZigZag Abuse (ZZA) consiste en abusar del movimiento zigzagueante de forma excesiva e irrealista para evitar recibir daño durante persecuciones o tiroteos."], "subs": [{"n": "23.1", "t": "Definición", "l": ["Se considera ZigZag Abuse cualquier movimiento exagerado y repetitivo (correr en zigzag constante) con el objetivo de explotar las mecánicas del juego y dificultar artificialmente que te disparen o te alcancen.", "BunnyJump (BJ): Saltar repetidamente para moverse más rápido de lo normal."]}, {"n": "23.2", "t": "Ejemplos Prohibidos", "l": ["Correr en zigzag de forma constante y extrema durante persecuciones a pie.", "Combinar zigzag con saltos repetitivos (bunny hopping) para evitar balas.", "Usar movimientos abusivos para escapar de detenciones o tiroteos sin justificación RP.", "Realizar zigzagueos exagerados incluso cuando el personaje está herido o cansado.", "Saltar multiples veces para conseguir ventaja o abusar de algun bug.", "Saltar para aprovecharse del entorno.", "Abusar de este movimiento de forma habitual sin rol coherente."]}, {"n": "23.3", "t": "Principios Generales", "l": ["Los movimientos deben ser realistas y coherentes con la situación del personaje.", "Se permite correr o esquivar de forma natural, pero no explotar mecánicas de movimiento de manera abusiva.", "El roleplay y el FearRP deben prevalecer sobre intentar “ganar” mediante mecánicas."]}, {"n": "23.4", "t": "Sanciones", "l": ["El ZigZag Abuse es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal, dependiendo de la reiteración y el impacto en otros jugadores."]}]}, {"id": "gen-24", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "24", "titulo": "Bug Abuse (BA) - Lag Abuse (LA)", "tag": "Prohibido", "intro": ["El Bug Abuse y Lag Abuse consisten en explotar fallos del juego o la conexión para obtener ventajas injustas o romper la inmersión."], "subs": [{"n": "24.1", "t": "Definición", "l": ["Bug Abuse (BA): Utilizar errores, glitches o mecánicas no intencionadas del juego en beneficio propio.", "Lag Abuse (LA): Explotar la mala conexión o provocar lag de forma intencionada para evitar consecuencias o ganar ventaja."]}, {"n": "24.2", "t": "Ejemplos Prohibidos", "l": ["Usar glitches para atravesar paredes, duplicar objetos, o entrar en zonas inaccesibles.", "Utilizar la camara libre o tercera camara para ver mas alla de lo posible.", "Explotar bugs de vehículos (volar, atravesar map, etc.).", "Desconectarse intencionalmente durante una persecución, detención o tiroteo para evitar la muerte o arresto.", "Moverse o actuar durante picos de lag para esquivar balas o acciones.", "Abusar de cualquier fallo conocido del juego que rompa el balance o la lógica RP."]}, {"n": "24.3", "t": "Principios Generales", "l": ["Se debe jugar de forma limpia y reportar los bugs al Staff en lugar de explotarlos.", "El lag no justifica acciones abusivas.", "La integridad del servidor y el roleplay están por encima de cualquier beneficio personal."]}, {"n": "24.4", "t": "Sanciones", "l": ["El Bug Abuse y Lag Abuse son faltas graves. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, dependiendo de la gravedad, el beneficio obtenido y la reiteración."]}]}, {"id": "gen-25", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "25", "titulo": "Discriminación y Lenguaje Ofensivo", "tag": "Prohibido", "intro": ["La comunidad mantiene una política de tolerancia cero hacia la discriminación y el lenguaje ofensivo."], "subs": [{"n": "25.1", "t": "Definición", "l": ["Se considera discriminación o lenguaje ofensivo cualquier comentario, insulto, broma o comportamiento que ataque, humille o discrimine a una persona por su raza, género, orientación sexual, religión, nacionalidad, discapacidad o cualquier otra característica personal. Esto aplica dentro y fuera de rol"]}, {"n": "25.2", "t": "Ejemplos Prohibidos", "l": ["Uso de insultos racistas, xenófobos, homofóbicos, sexistas o de cualquier tipo.", "Comentarios despectivos sobre el aspecto físico, religión o identidad de otros jugadores.", "Bromas ofensivas que afecten a grupos vulnerables.", "Acoso o hate speech dirigido hacia cualquier miembro de la comunidad.", "Cualquier contenido discriminatorio en voz, chat o Discord.", "Se exige respeto absoluto hacia todos los miembros de la comunidad. El roleplay no justifica el uso de lenguaje ofensivo o discriminatorio. Todos los jugadores tienen derecho a un ambiente seguro y acogedor."]}, {"n": "25.3", "t": "Sanciones", "l": ["La discriminación y el lenguaje ofensivo son faltas muy graves. Las sanciones van desde amonestación inmediata hasta expulsión permanente del servidor y Discord, sin posibilidad de apelación en casos graves."]}]}, {"id": "gen-26", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "26", "titulo": "Canales de Voz “Chill” y “Play”", "tag": "Considera", "intro": ["En los canales de voz denominados “chill” o “play”, los usuarios pueden expresarse con mayor libertad, siempre respetando las normas básicas del servidor. Prohibido:", "Sexualizar a otros usuarios.", "Mencionar o insultar familiares/terceros de forma personal.", "Insultar o desacreditar al servidor. Los moderadores presentes en estos canales actúan bajo las mismas normas; no pueden amenazar sanciones sin incumplimiento claro."], "subs": []}, {"id": "gen-27", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "27", "titulo": "Roles +17 y +18", "tag": "Considera", "intro": ["Se permiten roles con contenido maduro (+17) en contextos de relaciones sentimentales, bodas, interacciones románticas, siempre que sean consensuados y discretos. Roles explícitamente +18 (contenido sexual gráfico) solo se permiten en privado (DMs o canales cerrados) y deben ser desenlazados de la comunidad donde no se promueven estas actitudes. Cualquier rol no consensuado o público será sancionado gravemente."], "subs": []}, {"id": "gen-28", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "28", "titulo": "Ventajas de las membresias", "tag": "Considera", "intro": ["Las Ventajas de las membresias son beneficios adicionales otorgados a los jugadores que adquieren membresía VIP o Booster. Estas ventajas son de carácter cosmético y de calidad de vida."], "subs": [{"n": "28.1", "t": "Definición", "l": ["Las de las membresias incluyen mejoras como vehículos exclusivos, uniformes especiales, dinero inicial, prioridad en cola y otros beneficios, pero no otorgan superioridad en el roleplay."]}, {"n": "28.2", "t": "Uso Permitido", "l": ["Utilizar vehículos, ropa y accesorios (Membresia) dentro del roleplay siempre que sea coherente con el personaje.", "Disfrutar de beneficios de calidad de vida (prioridad en cola, dinero extra, etc.).", "Mostrar el rango en Discord y en el servidor.", "Gozar de los beneficios pautados en las membresias", "Exigir prioridad en tickets"]}, {"n": "28.3", "t": "Restricciones y Prohibiciones", "l": ["No se permite usar ventajas para obtener beneficio injusto en roleplay (ej: usar vehículos blindados o excesivamente superiores en robos o persecuciones).", "Está prohibido usar las ventajas para hacer FailRP, Powergaming o VDM.", "Las ventajas no eximen de cumplir ninguna norma de la comunidad.", "Abusar de los beneficios para trollear o molestar a otros jugadores está prohibido.", "Los beneficios son unicos e intransferibles", "Cualquier intento de abuso, duplicación o estafa con pases será sancionado con ban permanente."]}, {"n": "28.4", "t": "Principios Generales", "l": ["Las ventajas son un apoyo para mejorar la experiencia, no una herramienta para tener ventaja sobre otros jugadores. Todos los miembros, independientemente de su rango, deben respetar las normas de roleplay por igual."]}, {"n": "28.5", "t": "Sanciones", "l": ["El mal uso de ventajas es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta la revocación temporal de beneficios o expulsión, según la gravedad."]}]}, {"id": "gen-29", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "29", "titulo": "Ayudas en soporte", "tag": "Soporte", "intro": ["Las ayudas en soporte son las solicitudes de asistencia que realizan los jugadores al Staff."], "subs": [{"n": "29.1", "t": "Definición", "l": ["Las ayudas en soporte son tickets o mensajes dirigidos al equipo de Staff para resolver problemas técnicos, dudas o reportes dentro del servidor."]}, {"n": "29.2", "t": "Uso Correcto", "l": ["Utiliza el canal o sistema de tickets correspondiente.", "Sé claro, educado y proporciona toda la información necesaria (capturas, videos, descripción del problema).", "Espera tu turno. No abuses abriendo múltiples tickets por el mismo problema.", "Solo usa el soporte para temas importantes (bugs, reportes de faltas graves, problemas técnicos, etc.)."]}, {"n": "29.3", "t": "Prohibiciones", "l": ["No se permite spamear tickets o mensajes al Staff.", "Está prohibido usar el soporte para bromas, trollear o temas sin importancia.", "No se permite insultar, exigir o faltar el respeto al Staff en los tickets.", "Queda prohibido abrir tickets para temas que ya estén explicados en la normativa.", "Se prohíbe estrictamente el usar amenazas de reporte como medio de intimidación o presión hacia otros jugadores."]}, {"n": "29.4", "t": "Principios Generales", "l": ["El soporte existe para ayudar a mantener un buen ambiente y solucionar problemas reales.", "La paciencia y el respeto son obligatorios en toda interacción con el Staff."]}, {"n": "29.5", "t": "Sanciones", "l": ["El abuso del sistema de soporte o faltar el respeto al Staff es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva."]}]}, {"id": "gen-30", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "30", "titulo": "AA (Admin Abuse)", "tag": "Soporte", "intro": ["El Admin Abuse es el uso indebido o abusivo de los poderes administrativos por parte del Staff."], "subs": [{"n": "30.1", "t": "Definición", "l": ["Se considera Admin Abuse cualquier acción en la que un miembro del Staff utilice sus privilegios administrativos de forma injusta, personal o que perjudique la experiencia de los jugadores."]}, {"n": "30.2", "t": "Ejemplos Prohibidos", "l": ["Usar comandos de Staff para beneficio personal (dinero, vehículos, items, etc.).", "Teletransportar, revivir o ayudar a amigos o a sí mismo durante situaciones de roleplay.", "Aplicar sanciones sin motivo válido o por motivos personales (rencores, favoritismos).", "Revelar información administrativa o usar conocimiento de Staff en el roleplay.", "Abusar de poderes para trollear, molestar o interferir negativamente en escenas de jugadores.", "Modificar el servidor o situaciones RP de forma arbitraria sin justificación."]}, {"n": "30.3", "t": "Principios Generales", "l": ["Los miembros del Staff deben actuar con imparcialidad, responsabilidad y transparencia.", "Los poderes administrativos solo deben usarse para ayudar al correcto funcionamiento del servidor y apoyar el roleplay.", "Cualquier acción administrativa debe priorizar el bienestar de la comunidad."]}, {"n": "30.4", "t": "Sanciones", "l": ["El Admin Abuse es una falta extremadamente grave. Puede conllevar desde la suspensión inmediata del cargo hasta la expulsión permanente del Staff y de la comunidad."]}]}, {"id": "gen-31", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "31", "titulo": "KAD/KHD (Kill Admin/Helper Duty)", "tag": "Soporte", "intro": ["El KAD/KHD consiste en matar, atacar o interrumpir de forma agresiva a un miembro del Staff mientras se encuentra en servicio administrativo o de ayuda."], "subs": [{"n": "31.1", "t": "Definición", "l": ["Se considera KAD/KHD cualquier acto de violencia o interferencia intencionada contra un Administrador, Moderador o Helper mientras está cumpliendo con sus funciones en el servidor."]}, {"n": "31.2", "t": "Ejemplos Prohibidos", "l": ["Atacar, disparar, secuestrar o atropellar a un Staff que esté identificado como en deber (Admin Duty o Helper Duty).", "Interrumpir una escena de Staff con acciones violentas sin justificación RP.", "Matar o intentar matar a un miembro del Staff visiblemente en servicio.", "Provocar o trollear a un Staff mientras está resolviendo reportes o ayudando a jugadores.", "Ignorar la identificación del Staff (nombres especiales, etiquetas, etc.) para atacarlos."]}, {"n": "31.3", "t": "Principios Generales", "l": ["Los miembros del Staff en deber administrativo merecen respeto y protección.", "Sus funciones son necesarias para el correcto funcionamiento de la comunidad.", "Cualquier conflicto con Staff debe resolverse de forma madura y a través de los canales adecuados."]}, {"n": "31.4", "t": "Sanciones", "l": ["El KAD/KHD es una falta muy grave. Las sanciones pueden ir desde una suspensión temporal larga hasta la expulsión definitiva de la comunidad, sin posibilidad de apelación en casos claros."]}]}, {"id": "gen-32", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "32", "titulo": "Sistema de apelaciones", "tag": "Soporte", "intro": ["El Sistema de Apelaciones permite a los jugadores solicitar la revisión de una sanción impuesta."], "subs": [{"n": "32.1", "t": "Definición", "l": ["Una apelación es la solicitud formal para revisar o modificar una sanción aplicada por el Staff."]}, {"n": "32.2", "t": "Procedimiento", "l": ["Las apelaciones deben realizarse exclusivamente a través de tickets en el canal correspondiente.", "Debes incluir:", "Tu nombre de Roblox y Discord.", "Número de sanción o motivo.", "Explicación clara y respetuosa de por qué crees que la sanción debe ser revisada.", "Evidencias (grabaciones, capturas, testigos, etc.).", "Solo se aceptará una apelación por sanción."]}, {"n": "32.3", "t": "Plazos y Limitaciones", "l": ["Las apelaciones deben realizarse dentro de los 7 días siguientes a la sanción.", "No se aceptan apelaciones con insultos, falta de respeto o intentos de manipulación.", "El Staff se reserva el derecho de aceptar o denegar la apelación."]}, {"n": "32.4", "t": "Principios Generales", "l": ["Las apelaciones deben ser honestas y basadas en hechos.", "En caso de ser denegado puede suprimir la sancion con servicio comunitario (Art.33).", "Puede pedir una re-apelacion con la alta administracion mediante el Art.34.", "El sistema existe para corregir errores, no para evitar consecuencias merecidas."]}, {"n": "32.5", "t": "Sanciones por Abuso", "l": ["Abusar del sistema de apelaciones, abrir tickets repetitivos o faltar el respeto al Staff durante el proceso es una falta grave. Esto puede resultar en aumento de la sanción original o nuevas sanciones."]}]}, {"id": "gen-33", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "33", "titulo": "Servicio Comunitario", "tag": "Apelaciones", "intro": ["El Servicio Comunitario es una sanción alternativa que consiste en realizar tareas útiles para la comunidad como forma de reparación."], "subs": [{"n": "33.1", "t": "Definición", "l": ["El Servicio Comunitario es una medida disciplinaria que obliga al jugador a cumplir horas de trabajo RP en beneficio de la comunidad (limpieza, ayuda en eventos, patrullas, etc.)."]}, {"n": "33.2", "t": "Procedimiento", "l": ["El Staff asignará las tareas correspondientes según la falta cometida.", "El jugador puede obtar por realizar servicio comunitario de manera voluntaria para anexar sus sanciones a una sola y mantenerla como una nota.", "El jugador debe completar las horas asignadas en el tiempo estipulado.", "Si el jugador acumula una cantidad de +5 sanciones tendra que obtar por servicio comunitario obligatorio o la expulsion del servidor.", "Se debe mantener una actitud positiva y rolear correctamente durante el servicio."]}, {"n": "33.3", "t": "Apelaciones", "l": ["Las apelaciones al Servicio Comunitario solo se aceptarán en casos de errores graves.", "Para apelar, debes abrir un ticket en la sección correspondiente con pruebas claras.", "Las apelaciones por \"no estar de acuerdo\" o \"fue sin intención\" generalmente no serán aceptadas."]}, {"n": "33.4", "t": "Sanciones por Incumplimiento", "l": ["No cumplir con el Servicio Comunitario o hacerlo de mala fe es una falta grave. Esto puede resultar en aumento de la sanción original o expulsión temporal del servidor."]}]}, {"id": "gen-34", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "34", "titulo": "Pagos mediante moneda real OOC", "tag": "Apelaciones", "intro": ["Este artículo regula los pagos con moneda real (OOC) para solicitar apelaciones o revisiones de sanciones."], "subs": [{"n": "34.1", "t": "Definición", "l": ["Se permite el pago con moneda real únicamente como opción para agilizar o solicitar una revisión especial de sanciones graves."]}, {"n": "34.2", "t": "Procedimiento", "l": ["El pago debe realizarse a través de los canales oficiales establecidos por la administración.", "El jugador debe abrir un ticket indicando que desea apelar mediante pago OOC.", "El monto y las condiciones de cada apelación serán definidos por el Staff según la gravedad de la sanción.", "No todos los casos son elegibles para apelación por pago."]}, {"n": "34.3", "t": "Limitaciones", "l": ["Este sistema no garantiza que la sanción sea levantada.", "Solo se aceptan pagos por apelaciones de sanciones graves (no faltas leves).", "El Staff se reserva el derecho de aceptar o rechazar la apelación incluso después del pago."]}, {"n": "34.4", "t": "Sanciones", "l": ["El uso de pagos OOC fuera de los canales oficiales o intentar sobornar al Staff es una falta extremadamente grave. Esto resultará en expulsión permanente sin posibilidad de apelación."]}]}, {"id": "gen-35", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "35", "titulo": "Cierre automático de tickets", "tag": "Soporte", "intro": ["Todo ticket abierto en el sistema de soporte Discord (reportes, apelaciones, dudas, quejas, solicitudes de eventos, etc.) debe ser gestionado de forma activa por el usuario que lo creó. Si transcurren 3 días naturales (72 horas) desde la apertura del ticket sin ninguna respuesta, interacción o aporte adicional por parte del solicitante (mensajes, evidencias, aclaraciones), el ticket se cerrará automáticamente con el estado “Cerrado por inactividad del usuario”.", "Esta medida busca:", "Evitar acumulación innecesaria de tickets abandonados", "Priorizar casos activos y urgentes", "Reducir carga administrativa al staff", "El cierre automático no impide abrir un nuevo ticket con el mismo asunto si el usuario decide retomarlo posteriormente, pero deberá explicar el contexto anterior y adjuntar referencias al ticket viejo (número o enlace)."], "subs": []}, {"id": "gen-36", "sec": "gen", "bloque": "", "bloqueT": "", "cap": "", "num": "36", "titulo": "Donaciones y pagos", "tag": "Sistema monetario", "intro": ["Las donaciones y pagos con dinero real son contribuciones voluntarias realizadas por los jugadores para apoyar el servidor. Esta actividad está estrictamente regulada."], "subs": [{"n": "36.1", "t": "Definición", "l": ["Se considera donación o pago cualquier transferencia de dinero real (bolívares, dólares, criptomonedas, gift cards u otros métodos) hacia la administración del servidor."]}, {"n": "36.2", "t": "Procedimiento Oficial", "l": ["Todas las donaciones y pagos deben realizarse exclusivamente a través de los métodos y cuentas oficiales anunciados por la administración.", "El jugador debe notificar mediante ticket una vez realizada la donación, incluyendo comprobante de pago. Posteriormente esperar la verificacion.", "Las donaciones no otorgan ventajas que afecten el equilibrio del roleplay (inmortalidad, impunidad, etc.).", "Los beneficios por donación serán entregados según los paquetes establecidos."]}, {"n": "36.3", "t": "Prohibiciones", "l": ["Está estrictamente prohibido realizar pagos OOC fuera de los canales oficiales.", "No se permite comprar, vender o intercambiar cuentas, vehículos, dinero IC, rangos o cualquier elemento del servidor por dinero real.", "Queda prohibido ofrecer o aceptar donaciones a cambio de favores administrativos, levantamiento de sanciones o trato preferencial.", "No se permite presionar, extorsionar o condicionar a otros jugadores para que donen."]}, {"n": "36.4", "t": "Responsabilidad", "l": ["Las donaciones son voluntarias y no reembolsables.", "La administración no se hace responsable por pagos realizados a cuentas no oficiales.", "Cualquier intento de estafa o fraude relacionado con donaciones será reportado y perseguido."]}, {"n": "36.5", "t": "Sanciones", "l": ["Cualquier violación a este artículo se considera una falta extremadamente grave.", "Las sanciones incluyen:", "Expulsión permanente del servidor y Discord.", "Posible reporte a las autoridades correspondientes en casos de fraude.", "Pérdida total de todos los beneficios adquiridos.", "No hay excepciones ni apelaciones para infracciones relacionadas con pagos irregulares de dinero real."]}]}, {"id": "ciu-1", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "1", "titulo": "Concepto Principal civil", "tag": "Importante", "intro": ["El Concepto Principal Civil establece las bases del roleplay para todos los jugadores que interpretan personajes civiles en VE:RP."], "subs": [{"n": "1.1", "t": "Definición", "l": ["El roleplay civil se centra en vivir una vida cotidiana realista dentro del universo del servidor. Los civiles son la base de la sociedad y deben actuar conforme a su profesión, personalidad y situación económica."]}, {"n": "1.2", "t": "Principios Fundamentales", "l": ["Actúa siempre como un ciudadano común de Liberty County.", "Respeta las leyes y normas sociales del estado.", "Desarrolla tu personaje de forma progresiva (trabajo, relaciones, economía, etc.).", "Evita comportamientos propios de facciones (policía, delincuencia organizada) a menos que formes parte de ellas.", "Prioriza la inmersión y la interacción con otros civiles y autoridades."]}, {"n": "1.3", "t": "Conductas Recomendadas", "l": ["Busca empleo, crea negocios o participa en la economía legal.", "Mantén conversaciones y acciones coherentes con tu edad, profesión y trasfondo.", "Colabora con otros jugadores para crear historias interesantes.", "Respeta las propiedades privadas y el espacio de los demás."]}, {"n": "1.4", "t": "Sanciones", "l": ["Incumplir el Concepto Principal Civil de forma reiterada se considera FailRP. Las sanciones pueden ir desde una advertencia hasta expulsión temporal, según la gravedad."]}]}, {"id": "ciu-2", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "2", "titulo": "Ingreso a departamentos", "tag": "Considera", "intro": ["El Ingreso a Departamentos regula el proceso para unirse a facciones oficiales como Policía, EMS, Bomberos o Gobierno."], "subs": [{"n": "2.1", "t": "Definición", "l": ["Se entiende como ingreso a departamentos el proceso mediante el cual un jugador pasa a formar parte de una facción oficial del servidor. Este proceso busca garantizar que solo ingresen jugadores comprometidos con el roleplay de calidad."]}, {"n": "2.2", "t": "Requisitos para Ingresar", "l": ["Ser mayor de 12 años.", "Tener al menos 20 horas de juego como civil.", "Demostrar buen comportamiento y respeto a las normas de la comunidad.", "Aprobar el proceso de selección del departamento correspondiente (entrevista, examen o prueba práctica).", "Contar con un personaje coherente y realista para el rol solicitado.", "Unicamente se puede estar en un departamento principal a la vez. Por otro lado solo se puede estar en dos secundarios a la vez.", "Haber creado su DNI IC"]}, {"n": "2.3", "t": "Proceso de Ingreso", "l": ["Postular a través del canal correspondiente en Discord.", "Completar todas las etapas del proceso de reclutamiento establecido por cada departamento.", "Una vez aceptado, recibir entrenamiento inicial antes de patrullar o ejercer funciones oficiales.", "Mantener actividad mínima y buen desempeño para permanecer en el departamento."]}, {"n": "2.4", "t": "Principios Generales", "l": ["Los usuarios que renuncien o sean removidos de un departamento deberán cumplir un período de espera de siete (7) días antes de poder ingresar a otro departamento. Durante la evaluación de ingreso, podrán considerarse los motivos de su salida o despido del departamento anterior.", "El ingreso a departamentos es un privilegio, no un derecho.", "Los miembros de facciones deben dar ejemplo de buen roleplay y respeto a las normas.", "Abusar de la autoridad o posición dentro del departamento está estrictamente prohibido."]}, {"n": "2.5", "t": "Sanciones", "l": ["Incumplir los requisitos o el proceso de ingreso se considera falta media. El mal desempeño reiterado o faltas graves dentro del departamento pueden resultar en expulsión del mismo y, en casos severos, de la comunidad."]}]}, {"id": "ciu-3", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "3", "titulo": "Trabajos publicos", "tag": "Importante", "intro": ["Los Trabajos Públicos y Empleos Secundarios son una forma legal y realista de generar ingresos para los personajes civiles."], "subs": [{"n": "3.1", "t": "Definición", "l": ["Los trabajos secundarios permiten a los jugadores obtener dinero mediante actividades laborales por turnos o tiempo definido. Todos estos empleos están bajo la gestión, administración y supervisión de asuntos internos."]}, {"n": "3.2", "t": "Cómo Ganar Dinero", "l": ["Realiza cualquiera de los trabajos públicos disponibles en el servidor.", "Trabaja durante el tiempo o turno establecido.", "Recopila evidencias de tu labor (tiempo trabajado y fotos)."]}, {"n": "3.3", "t": "Procedimiento de Cobro", "l": ["Para recibir el pago correspondiente debes:", "Abrir un ticket en el canal tickets.", "Presentar las pruebas de tu trabajo (evidencias del tiempo trabajado + fotos).", "Presentar evidencias de los cheques obtenidos por el juego.", "Esperar la evaluación del Staff.", "Una vez aprobado, se te añadirá el dinero a tu personaje.", "Nota: Todos los cobros de cheques por trabajos deben realizarse exclusivamente mediante ticket con las evidencias requeridas."]}, {"n": "3.4", "t": "Principios Generales", "l": ["Los trabajos públicos fomentan el roleplay económico y la vida civil realista.", "Se debe mantener una actitud profesional y coherente mientras se realiza el empleo.", "El abuso o falsificación de evidencias se considerará FailRP o estafa."]}, {"n": "3.5", "t": "Trabajos Disponibles y considerados publicos", "l": ["Cafeterias", "Bar", "Talleres", "Comida rapida", "Transporte publico", "Transporte privado", "Correos", "Basurrero", "Gasolineras", "Tiendas que esten en trabajos libres del juego y que no sean considerados departamentos."]}, {"n": "3.5", "t": "Sanciones", "l": ["Falsificar evidencias, cobrar sin haber trabajado o abusar del sistema es una falta grave. Las sanciones pueden ir desde la anulación del pago hasta sanciones disciplinarias más severas."]}]}, {"id": "ciu-4", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "4", "titulo": "DNI e Identificacion Personal", "tag": "Obligatorio", "intro": ["El Documento Nacional de Identidad (DNI) es el documento oficial que identifica a todos los ciudadanos."], "subs": [{"n": "4.1", "t": "Definición", "l": ["El DNI es obligatorio para todos los personajes civiles y sirve como principal medio de identificación ante autoridades y otros ciudadanos."]}, {"n": "4.2", "t": "Obligaciones", "l": ["Todo jugador debe portar su DNI en todo momento mientras rolea.", "Debes mostrar tu DNI cuando una autoridad lo solicite de forma legítima.", "El DNI debe contener información realista y coherente con tu personaje.", "Se prohíbe el uso de nombres ofensivos, vulgares, discriminatorios o que hagan referencia a celebridades o figuras públicas (ejemplos: “Cristiano Ronaldo”, “Rosa Melano”, etc.).", "No está permitido rolear la creación, posesión o uso de documentos falsificados ni identificaciones alternas.", "Queda prohibida la compraventa, cesión o intercambio de DNI entre jugadores, ya sea por medios IC u OOC."]}, {"n": "4.3", "t": "Excepciones y Justificación", "l": ["No portar el DNI se considera Evadir Roleplay, salvo que puedas demostrar mediante grabaciones que lo dejaste en casa u otro lugar como acción RP previa."]}, {"n": "4.4", "t": "Principios Generales", "l": ["La identificación personal es fundamental para un roleplay realista y ordenado. Negarse a identificarse sin motivo válido puede derivar en detención o sanciones."]}, {"n": "4.5", "t": "Sanciones", "l": ["No portar el DNI o negarse a mostrarlo sin justificación es una falta media. La reiteración puede considerarse Evadir Roleplay y recibir sanciones más graves."]}]}, {"id": "ciu-5", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "5", "titulo": "Vehiculos Personales", "tag": "Obligatorio", "intro": ["Los Vehículos Personales son aquellos adquiridos o asignados a personajes civiles para uso diario y roleplay."], "subs": [{"n": "5.1", "t": "Definición", "l": ["Los vehículos personales son parte del patrimonio del personaje y deben usarse de forma coherente con su nivel económico y estilo de vida."]}, {"n": "5.2", "t": "Requisitos y Obligaciones", "l": ["Todo vehículo personal debe tener placa con formato realista AAA-###.", "Debes mantener tu vehículo en buen estado visual y mecánico.", "Solo puedes conducir vehículos que correspondan a tu personaje (no usar vehículos de lujo sin justificación RP).", "Los vehículos deben estar estacionados en lugares permitidos cuando no se usen."]}, {"n": "5.3", "t": "Prohibiciones", "l": ["No se permite el blindaje de vehículos personales.", "Está prohibido usar colores extremadamente chillones o irrealistas.", "No se permite robar, vender o modificar vehículos de otros jugadores sin su consentimiento RP.", "Queda prohibido usar vehículos personales para cometer crímenes de forma constante o abusiva."]}, {"n": "5.4", "t": "Principios Generales", "l": ["Los vehículos personales deben contribuir a la inmersión y al roleplay realista. El uso de vehículos debe respetar las normas de conducción realista establecidas en el servidor."]}, {"n": "5.5", "t": "Sanciones", "l": ["Incumplir las normas de vehículos personales es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta la confiscación del vehículo o sanciones más severas según la reiteración."]}]}, {"id": "ciu-6", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "6", "titulo": "Viviendas Personales", "tag": "Obligatorio", "intro": ["Las Viviendas Personales son propiedades que los personajes pueden adquirir para vivir y desarrollar su roleplay."], "subs": [{"n": "6.1", "t": "Definición", "l": ["Las viviendas personales son espacios privados donde el jugador puede almacenar objetos, descansar y realizar roleplay cotidiano o familiar."]}, {"n": "6.2", "t": "Obligaciones y Uso", "l": ["Solo el propietario y las personas autorizadas por él pueden entrar libremente.", "Debes mantener tu vivienda con un rol coherente (limpieza, muebles, etc.).", "Se permite rolear dentro de la vivienda siempre que no afecte la experiencia de otros jugadores.", "Las viviendas deben usarse de forma realista según el nivel económico del personaje."]}, {"n": "6.3", "t": "Prohibiciones", "l": ["Está prohibido entrar a viviendas ajenas sin permiso RP válido (allanamiento).", "No se permite usar la vivienda para almacenar objetos de forma irrealista o abusiva.", "Queda prohibido realizar robos o allanamientos sin una razón RP sólida y previa interacción.", "No se permite spawnear o modificar propiedades fuera de las mecánicas permitidas.", "No se permite spawnear nuevos vehiculos en el garaje.", "No se permite bugear intencionalmente las fisicas irrealistas de la casa."]}, {"n": "6.4", "t": "Principios Generales", "l": ["Las viviendas personales son un espacio importante para el desarrollo del personaje y su historia.", "Se debe respetar la privacidad y propiedad de los demás jugadores."]}, {"n": "6.5", "t": "Sanciones", "l": ["Incumplir las normas de viviendas personales es una falta media a grave. El allanamiento injustificado o abuso de propiedades puede resultar en sanciones severas, incluyendo expulsión temporal."]}]}, {"id": "ciu-7", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "7", "titulo": "Armas blancas", "tag": "Obligatorio", "intro": ["Las armas blancas (cuchillos, navajas, objetos punzantes, etc.) son herramientas de uso limitado y deben emplearse con responsabilidad dentro del roleplay."], "subs": [{"n": "7.1", "t": "Definición", "l": ["Las armas blancas son objetos de uso cotidiano o defensivo que pueden portarse y usarse siempre que se ajuste al contexto del roleplay."]}, {"n": "7.2", "t": "Obligaciones y Uso Permitido", "l": ["Solo se permite portar y usar armas blancas cuando corresponda al trasfondo y rol del personaje.", "Su uso debe estar justificado (defensa propia, trabajo, contexto RP previo).", "Se debe dar oportunidad de reacción al otro jugador antes de usar el arma."]}, {"n": "7.3", "t": "Prohibiciones", "l": ["No se permite atacar o amenazar con armas blancas de forma aleatoria (RDM).", "Está prohibido usarlas de forma irrealista o excesiva (powergaming).", "No se permite portar armas blancas de forma constante sin justificación RP.", "Queda prohibido usarlas en zonas seguras o contra personas indefensas sin motivo válido."]}, {"n": "7.4", "t": "Principios Generales", "l": ["El uso de armas blancas debe ser coherente con la personalidad y situación del personaje.", "Se prioriza siempre el roleplay y la escalada natural de los conflictos."]}, {"n": "7.5", "t": "Sanciones", "l": ["El mal uso de armas blancas es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, especialmente si deriva en RDM o FailRP."]}]}, {"id": "ciu-8", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "8", "titulo": "Armas de Fuego", "tag": "Obligatorio", "intro": ["Las armas de fuego son elementos de alto riesgo y deben usarse con máxima responsabilidad dentro del roleplay."], "subs": [{"n": "8.1", "t": "Definición", "l": ["Las armas de fuego incluyen pistolas, rifles, escopetas y cualquier otra arma letal de proyectiles. Su posesión y uso están fuertemente regulados."]}, {"n": "8.2", "t": "Uso Permitido", "l": ["Solo se permite portar armas de fuego si el personaje tiene una justificación legal o criminal coherente.", "Su uso debe estar precedido de una interacción RP clara y escalada progresiva.", "Se debe respetar el FearRP en todo momento (rendirse ante amenaza creíble)."]}, {"n": "8.3", "t": "Prohibiciones", "l": ["Está prohibido disparar o amenazar con armas de fuego sin motivo RP válido (RDM).", "No se permite el uso excesivo o irrealista de armas (Powergaming).", "Queda prohibido portar armas de fuego de forma constante sin justificación.", "No se permite usar armas en zonas seguras ni contra civiles indefensos sin razón justificada.", "No se permite portar armas de fuego con la justificacion de \"Es para defensa personal\""]}, {"n": "8.4", "t": "Principios Generales", "l": ["Las armas de fuego deben usarse como último recurso.", "Todo tiroteo o amenaza debe tener un contexto roleable y coherente.", "La vida del personaje siempre debe ser valorada."]}, {"n": "8.5", "t": "Sanciones", "l": ["El mal uso de armas de fuego es una falta muy grave. Las sanciones pueden ir desde expulsión temporal hasta expulsión definitiva del servidor, especialmente en casos de RDM o FailRP."]}]}, {"id": "ciu-9", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "9", "titulo": "Objetos IC", "tag": "", "intro": ["Los Objetos IC son todos aquellos elementos que tu personaje porta o utiliza dentro del roleplay."], "subs": [{"n": "9.1", "t": "Definición", "l": ["Los objetos IC incluyen dinero, armas, drogas, herramientas, documentos, teléfonos y cualquier otro item que forme parte de la historia de tu personaje."]}, {"n": "9.2", "t": "Obligaciones", "l": ["Todo objeto que uses o portes debe estar roleado correctamente.", "Debes tener una justificación RP coherente para poseer objetos valiosos o ilegales.", "Los objetos deben ser descritos mediante comandos /me o /do cuando sea necesario."]}, {"n": "9.3", "t": "Prohibiciones", "l": ["No se permite tener objetos sin justificación RP (metagaming).", "Está prohibido rolear posesión de objetos imposibles o ilógicos para tu personaje.", "No se permite duplicar o generar objetos de forma irrealista.", "Queda prohibido usar objetos para realizar FailRP o Powergaming."]}, {"n": "9.4", "t": "Principios Generales", "l": ["Los objetos IC deben contribuir a enriquecer el roleplay y la historia de tu personaje.", "La posesión y uso de objetos debe ser siempre coherente y realista."]}, {"n": "9.5", "t": "Sanciones", "l": ["El mal uso de objetos IC es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, según la gravedad y reiteración."]}]}, {"id": "ciu-10", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "10", "titulo": "Interaccion con Civiles", "tag": "Considera", "intro": ["La interacción con civiles es uno de los pilares del roleplay en Liberty County y debe realizarse con respeto y profesionalidad."], "subs": [{"n": "10.1", "t": "Definición", "l": ["Se refiere a toda interacción entre jugadores civiles."]}, {"n": "10.2", "t": "Reglas de Interacción", "l": ["Trata a los civiles con respeto y educación.", "Las detenciones, registros o intervenciones deben tener una razón RP válida.", "Da oportunidad de diálogo antes de recurrir a acciones agresivas.", "Evita actitudes tóxicas, abuso de autoridad o powergaming contra civiles."]}, {"n": "10.3", "t": "Prohibiciones", "l": ["No se permite insultar, humillar o acosar a civiles.", "Está prohibido el uso excesivo de fuerza sin justificación.", "No se permite interrumpir roleplay civil sin motivo RP.", "Queda prohibido el metagaming o el uso de información OOC contra civiles."]}, {"n": "10.4", "t": "Principios Generales", "l": ["Los civiles son la base de la sociedad.", "Todas las interacciones deben contribuir a crear una experiencia inmersiva y agradable para todos los jugadores.", "El respeto mutuo es obligatorio."]}, {"n": "10.5", "t": "Sanciones", "l": ["Incumplir las normas de interacción con civiles es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, especialmente en casos de abuso de autoridad o toxicidad."]}]}, {"id": "ciu-11", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "11", "titulo": "Interaccion con Funcionarios", "tag": "Considera", "intro": ["La interacción con funcionarios públicos (Policía, EMS, Bomberos y Gobierno) debe realizarse con respeto y cooperación dentro del roleplay."], "subs": [{"n": "11.1", "t": "Definición", "l": ["Se refiere a toda interacción entre personajes civiles y funcionarios del estado durante el cumplimiento de sus deberes."]}, {"n": "11.2", "t": "Obligaciones del Civil", "l": ["Debes identificarte cuando un funcionario lo solicite de forma legítima.", "Colabora de manera pacífica durante detenciones, registros o procedimientos oficiales.", "Respeta las órdenes razonables de los funcionarios."]}, {"n": "11.3", "t": "Prohibiciones", "l": ["No se permite insultar, agredir verbalmente o faltar el respeto a funcionarios.", "Está prohibido matar a funcionarios en situaciones de código 10-11 (parada de transito).", "No está permitido pararse inmediatamente después de recibir un taser. Debes rolear el efecto del taser de forma realista.", "Está prohibido interferir en procedimientos oficiales sin motivo RP válido.", "No se permite el uso de armas o violencia contra funcionarios sin una escalada RP coherente."]}, {"n": "11.4", "t": "Principios Generales", "l": ["Los funcionarios representan la autoridad del estado.", "La interacción debe ser realista y contribuir a una buena experiencia de roleplay para ambas partes.", "El respeto mutuo es obligatorio."]}, {"n": "11.5", "t": "Sanciones", "l": ["Incumplir las normas de interacción con funcionarios es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, especialmente en casos de resistencia excesiva o toxicidad."]}]}, {"id": "ciu-12", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "12", "titulo": "Provocaciones IC", "tag": "Considera", "intro": ["Las provocaciones IC son acciones o comentarios dentro del roleplay que buscan generar conflicto o reacción de otros personajes."], "subs": [{"n": "12.1", "t": "Definición", "l": ["Se entiende por provocación IC cualquier acción, gesto, palabra o comportamiento realizado dentro del rol con el fin de desafiar, molestar o iniciar un conflicto con otro personaje."]}, {"n": "12.2", "t": "Uso Permitido", "l": ["Las provocaciones deben ser coherentes con la personalidad y situación de tu personaje.", "Se permiten siempre que formen parte de una escena RP natural y no afecten gravemente la experiencia de otros jugadores.", "Deben dar oportunidad de respuesta al otro jugador."]}, {"n": "12.3", "t": "Prohibiciones", "l": ["No se permiten provocaciones excesivas, repetitivas o tóxicas que busquen frustrar al otro jugador.", "Está prohibido usar provocaciones para justificar RDM, VDM o FailRP.", "No se permite llevar provocaciones IC al plano OOC (rencores personales).", "Queda prohibido el uso de insultos o lenguaje extremadamente ofensivo como provocación."]}, {"n": "12.4", "t": "Principios Generales", "l": ["Las provocaciones IC deben enriquecer el roleplay y no convertirse en una herramienta de acoso.", "Se debe mantener un equilibrio entre conflicto interesante y respeto a los demás jugadores."]}, {"n": "12.5", "t": "Sanciones", "l": ["El abuso de provocaciones IC es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, según la reiteración y el impacto causado."]}]}, {"id": "ciu-13", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "13", "titulo": "Creacion de empresas", "tag": "", "intro": ["La creación de empresas permite a los jugadores desarrollar negocios y contribuir a la economía del servidor."], "subs": [{"n": "13.1", "t": "Definición", "l": ["Las empresas son negocios legales que los personajes pueden crear y administrar para generar ingresos y roleplay económico."]}, {"n": "13.2", "t": "Requisitos para Crear una Empresa", "l": ["Para crear una empresa debes presentar:", "Nombre de la Empresa.", "Logo de la Empresa.", "Historia de la Empresa.", "Motivo por el cual se crea la empresa."]}, {"n": "13.3", "t": "Procedimiento y Obligaciones", "l": ["Una vez aprobada la empresa, esta pasa a ser trabajo secundario obligatorio.", "Los trabajos principales permitidos son: CPNB, FANB, GNB Bomberos o Protección Civil.", "Ejemplo: Si creas la empresa Prosegur, esta obligatoriamente se convierte en tu trabajo secundario."]}, {"n": "13.4", "t": "Obligaciones Adicionales", "l": ["Mantener un roleplay activo y coherente dentro de la empresa.", "Mantener un DNI IC vigente", "Cumplir con las leyes del estado (impuestos, permisos, etc.).", "Proporcionar un ambiente RP adecuado para empleados y clientes."]}, {"n": "13.5", "t": "Prohibiciones", "l": ["No se permiten empresas ilegales sin aprobación previa del Staff.", "Está prohibido usar la empresa para realizar FailRP o estafas OOC.", "No se permite abandonar la empresa sin justificación RP o sin notificar al Staff.", "Para que la empresa cuente para lavado de dinero debe de presentar actividad."]}, {"n": "13.6", "t": "Sanciones", "l": ["Incumplir las normas de creación y manejo de empresas es una falta media a grave. Las sanciones pueden incluir el cierre de la empresa, pérdida de inversión o sanciones disciplinarias al propietario."]}]}, {"id": "ciu-14", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "14", "titulo": "Pago de impuestos", "tag": "", "intro": ["En desarrollo."], "subs": []}, {"id": "ciu-15", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "15", "titulo": "Solicitud de roles especiales", "tag": "", "intro": ["La solicitud de roles especiales permite a los jugadores pedir permisos temporales para roles o situaciones específicas."], "subs": [{"n": "15.1", "t": "Definición", "l": ["Los roles especiales son permisos temporales para realizar actividades que normalmente requieren autorización (eventos, roles temporales, accesos especiales, etc.)."]}, {"n": "15.2", "t": "Procedimiento de Solicitud", "l": ["Para solicitar un rol especial debes ir al canal correspondiente y utilizar el siguiente formato:", "Solicitud de Permiso", "Usuario de Roblox:", "Usuario de Discord:", "Tiempo de Permiso:", "Detalle de Permiso:", "Fecha del Permiso:", "Imagen si lo requiere:", "Nota: Los permisos no deben superar las 2 horas."]}, {"n": "15.3", "t": "Principios Generales", "l": ["Todas las solicitudes serán evaluadas por el Staff.", "El permiso debe usarse solo para el propósito solicitado.", "No se permite abusar de los roles especiales."]}, {"n": "15.4", "t": "Sanciones", "l": ["El mal uso de roles especiales o falsificar información en la solicitud es una falta grave. Las sanciones pueden ir desde la revocación del permiso hasta sanciones disciplinarias más severas."]}]}, {"id": "ciu-16", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "16", "titulo": "Entornos y proximidad", "tag": "", "intro": ["Las reglas de entornos y proximidad garantizan un roleplay realista según la cercanía física entre personajes."], "subs": [{"n": "16.1", "t": "Definición", "l": ["Se refiere a cómo los jugadores deben interactuar según la distancia y el entorno en el que se encuentran."]}, {"n": "16.2", "t": "Reglas de Proximidad", "l": ["Solo puedes interactuar o escuchar conversaciones cuando tu personaje está lo suficientemente cerca.", "Usa el chat cercano o comandos /me para acciones que requieren proximidad.", "No puedes reaccionar a eventos o conversaciones que ocurren fuera de tu campo visual o auditivo.", "Es obligatorio utilizar los canales VC en el servidor en caso de no poder usar la comunicacion interna del juego.", "Respeta los entornos: no puedes ver a través de paredes, puertas cerradas o edificios."]}, {"n": "16.3", "t": "Prohibiciones", "l": ["Está prohibido el metagaming por proximidad (saber lo que ocurre lejos de ti).", "No se permite espiar o escuchar conversaciones privadas sin justificación RP.", "Queda prohibido usar mecánicas del juego para obtener información irrealista del entorno."]}, {"n": "16.4", "t": "Principios Generales", "l": ["El roleplay debe ser coherente con la distancia física y el entorno.", "Esto ayuda a mantener la inmersión y evita abusos de información."]}, {"n": "16.5", "t": "Sanciones", "l": ["Incumplir las reglas de entornos y proximidad se considera metagaming o FailRP. Las sanciones pueden ir desde una advertencia hasta expulsión temporal, según la gravedad."]}]}, {"id": "ciu-17", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "17", "titulo": "Interaccion con delictivos", "tag": "", "intro": ["La interacción con delictivos regula el contacto entre civiles, funcionarios y personajes con comportamiento criminal."], "subs": [{"n": "17.1", "t": "Definición", "l": ["Se refiere a toda interacción RP entre jugadores y personajes que realizan actividades ilegales o pertenecen al mundo delictivo."]}, {"n": "17.2", "t": "Reglas Generales", "l": ["Las interacciones deben ser coherentes y realistas según el contexto.", "Los civiles pueden interactuar con delictivos siempre que exista una razón RP válida.", "Los funcionarios deben seguir procedimientos legales durante detenciones o investigaciones.", "Se debe respetar el FearRP en todo momento durante confrontaciones."]}, {"n": "17.3", "t": "Prohibiciones", "l": ["No se permite matar o atacar a delictivos sin escalada RP adecuada.", "Está prohibido el metagaming o usar información OOC contra personajes delictivos.", "No se permite provocar o acosar constantemente a delictivos sin motivo RP.", "Queda prohibido romper el rol durante persecuciones o robos."]}, {"n": "17.4", "t": "Principios Generales", "l": ["Las interacciones con delictivos deben generar roleplay de calidad y tensión realista.", "Tanto civiles como autoridades deben actuar con coherencia y respeto mutuo."]}, {"n": "17.5", "t": "Sanciones", "l": ["Incumplir las normas de interacción con delictivos es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva, especialmente si se genera RDM o FailRP."]}]}, {"id": "ciu-18", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "18", "titulo": "Noticieros", "tag": "", "intro": ["Los noticieros son medios de comunicación oficiales que informan eventos relevantes del servidor."], "subs": [{"n": "18.1", "t": "Definición", "l": ["Los noticieros son canales o medios RP encargados de transmitir noticias, reportajes y eventos importantes de Liberty County."]}, {"n": "18.2", "t": "Requisitos", "l": ["Solo los jugadores autorizados pueden transmitir como periodistas o presentadores.", "Todo contenido debe ser veraz y basado en eventos reales ocurridos en el servidor.", "Se debe mantener un tono profesional y neutral durante las transmisiones.", "Las transmisiones deben tener una duración y calidad adecuada."]}, {"n": "18.3", "t": "Prohibiciones", "l": ["No se permite transmitir información falsa o sensacionalista sin base RP.", "Está prohibido revelar información OOC o privada en los noticieros.", "No se permite usar los noticieros para difamar, acosar o atacar personalmente a jugadores.", "Queda prohibido interrumpir roleplay con transmisiones innecesarias."]}, {"n": "18.4", "t": "Principios Generales", "l": ["Los noticieros enriquecen la inmersión del servidor y ayudan a crear una sociedad viva.", "Los periodistas deben actuar con ética y responsabilidad."]}, {"n": "18.5", "t": "Sanciones", "l": ["Incumplir las normas de noticieros es una falta media a grave. Las sanciones pueden ir desde una advertencia hasta la revocación del rol o expulsión temporal."]}]}, {"id": "ciu-19", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "19", "titulo": "Gobierno", "tag": "", "intro": ["En desarrollo."], "subs": []}, {"id": "ciu-20", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "20", "titulo": "Enfermedades, discapacidades y adicciones", "tag": "Importante", "intro": ["Las enfermedades, discapacidades y adicciones deben ser roleadas con madurez, respeto y realismo."], "subs": [{"n": "20.1", "t": "Definición", "l": ["Se refiere al roleo de condiciones médicas, físicas, mentales o adicciones que afecten al personaje de forma permanente o temporal."]}, {"n": "20.2", "t": "Requisitos para Rolear", "l": ["Debes investigar y rolear la condición de forma realista y coherente.", "La condición debe estar justificada en la historia del personaje.", "Se debe rolear tanto las limitaciones como las consecuencias diarias.", "No se permite usar enfermedades o discapacidades para obtener ventajas injustas."]}, {"n": "20.3", "t": "Prohibiciones", "l": ["No se permite rolear enfermedades o discapacidades de forma ofensiva, estereotipada o burlona.", "Está prohibido usar estas condiciones para evadir consecuencias RP o justificar FailRP.", "No se permite rolear adicciones de forma exagerada o para generar drama innecesario.", "Queda prohibido rolear condiciones graves sin conocimiento básico o sin aprobación del Staff en casos extremos.", "Las adicciones deben de ser mediante permisos especiales (Art. 15)"]}, {"n": "20.4", "t": "Principios Generales", "l": ["El roleo de enfermedades, discapacidades y adicciones debe ser respetuoso y contribuir a una historia profunda del personaje.", "Se prioriza siempre la sensibilidad y el respeto hacia los demás jugadores."]}, {"n": "20.5", "t": "Sanciones", "l": ["El mal uso o roleo ofensivo de enfermedades, discapacidades y adicciones es una falta grave. Las sanciones pueden ir desde una advertencia hasta expulsión temporal o definitiva."]}]}, {"id": "ciu-21", "sec": "ciu", "bloque": "", "bloqueT": "", "cap": "", "num": "21", "titulo": "Backstory", "tag": "Importante", "intro": ["El Backstory (historia de fondo) es la biografía y pasado de tu personaje."], "subs": [{"n": "21.1", "t": "Definición", "l": ["El Backstory es el conjunto de experiencias, origen, familia, educación y eventos pasados que definen la personalidad y motivaciones de tu personaje."]}, {"n": "21.2", "t": "Requisitos", "l": ["Todo personaje debe tener un backstory coherente, realista y acorde con el universo de Liberty County.", "Debe ser lógico y no contener elementos extremadamente fantasiosos o contradictorios.", "El backstory debe influir en el comportamiento actual del personaje."]}, {"n": "21.3", "t": "Prohibiciones", "l": ["No se permiten backstories que incluyan personajes famosos, multimillonarios sin justificación o eventos imposibles.", "Está prohibido cambiar drásticamente el backstory sin justificación RP o aprobación del Staff.", "No se permite usar el backstory para justificar metagaming, powergaming o FailRP."]}, {"n": "21.4", "t": "Principios Generales", "l": ["Un buen backstory enriquece el roleplay y ayuda a mantener la consistencia del personaje.", "Debe servir como base para crear historias interesantes y coherentes."]}, {"n": "21.5", "t": "Sanciones", "l": ["Incumplir las normas del Backstory es una falta media. La reiteración o el uso abusivo puede considerarse FailRP y recibir sanciones más graves."]}]}, {"id": "dep-A-1", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 1: Disposiciones Generales", "num": "1", "titulo": "Principios y Valores Departamentales", "tag": "", "intro": ["Los departamentos oficiales representan la autoridad y el servicio público. Por esta razón, todos sus miembros deben regirse por principios y valores fundamentales."], "subs": [{"n": "1.1", "t": "Principios Fundamentales", "l": ["Respeto: Tratar a todos los ciudadanos y compañeros con dignidad, cortesía y profesionalismo, independientemente de su origen, rol o situación.", "Integridad: Actuar con honestidad, transparencia y ética en todo momento. No se tolerará la corrupción ni el abuso de autoridad.", "Servicio Público: Priorizar el bienestar de la comunidad por encima de intereses personales.", "Profesionalismo: Mantener un alto estándar de conducta, tanto en servicio como fuera de él.", "Trabajo en Equipo: Colaborar de forma efectiva con otros departamentos y compañeros para cumplir la misión."]}, {"n": "1.2", "t": "Compromiso", "l": ["Todo miembro de un departamento se compromete a:", "Ser un ejemplo de buen roleplay para la comunidad.", "Cumplir y hacer cumplir las normas del servidor.", "Actuar siempre dentro de la legalidad y los procedimientos establecidos."]}, {"n": "1.3", "t": "Sanciones", "l": ["La violación grave de estos principios y valores será considerada una falta grave. Las sanciones pueden incluir amonestación, suspensión temporal o expulsión definitiva del departamento."]}]}, {"id": "dep-A-2", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 1: Disposiciones Generales", "num": "2", "titulo": "Código de Conducta y Ética", "tag": "", "intro": ["Los miembros de los departamentos oficiales deben mantener un comportamiento ejemplar tanto dentro como fuera de servicio, representando los valores de la institución."], "subs": [{"n": "2.1", "t": "Conducta General", "l": ["Actuar siempre con profesionalismo, cortesía y respeto hacia civiles, compañeros y miembros de otros departamentos.", "Mantener un lenguaje adecuado y profesional en canales de radio y voz.", "Prohibido el uso de insultos, bromas de mal gusto o lenguaje vulgar mientras se está en servicio.", "Evitar cualquier tipo de discriminación por raza, género, orientación sexual, religión o cualquier otra condición."]}, {"n": "2.2", "t": "Ética Profesional", "l": ["No se permitirá el abuso de autoridad, corrupción, sobornos o favoritismos.", "Toda información obtenida en el ejercicio de las funciones debe tratarse con confidencialidad.", "Se prohíbe utilizar recursos del departamento (vehículos, equipamiento, información) para beneficio personal.", "Los miembros deben evitar conflictos de interés entre su rol oficial y actividades delictivas."]}, {"n": "2.3", "t": "Conducta Fuera de Servicio", "l": ["Aunque no estén en servicio, los miembros representan a su departamento. Por lo tanto, deben mantener una conducta adecuada que no dañe la imagen de la institución.", "Se recomienda evitar roleplay delictivo grave mientras se pertenezca activamente a un departamento oficial."]}, {"n": "2.4", "t": "Sanciones", "l": ["La violación al Código de Conducta y Ética será sancionada según su gravedad:", "Faltas leves: Amonestación o suspensión temporal.", "Faltas graves: Expulsión del departamento y posible sanción general."]}]}, {"id": "dep-A-3", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 1: Disposiciones Generales", "num": "3", "titulo": "Jerarquía y Cadena de Mando", "tag": "", "intro": ["La jerarquía y cadena de mando es fundamental para el correcto funcionamiento de los departamentos oficiales."], "subs": [{"n": "3.1", "t": "Principio de Jerarquía", "l": ["Todo miembro debe respetar la estructura jerárquica del departamento. Las órdenes de un superior deben ser acatadas siempre que sean legales y éticas."]}, {"n": "3.2", "t": "Obligaciones", "l": ["Los subordinados deben obedecer las órdenes legítimas de sus superiores.", "Los superiores deben ejercer su autoridad con responsabilidad, respeto y profesionalismo.", "Está prohibido discutir órdenes en público o frente a civiles. Las dudas deben resolverse en privado.", "Todo miembro tiene derecho a cuestionar órdenes que considere ilegales o antiéticas, pero debe seguir el procedimiento establecido."]}, {"n": "3.3", "t": "Prohibiciones", "l": ["Insubordinación: Negarse a cumplir órdenes legítimas sin justificación válida.", "Abuso de autoridad: Usar el rango para humillar, acosar o favorecer injustamente a otros miembros.", "Saltarse la cadena de mando sin motivo justificado."]}, {"n": "3.4", "t": "Principios Generales", "l": ["La cadena de mando existe para garantizar orden, eficiencia y coordinación.", "El respeto mutuo entre rangos es obligatorio para mantener un buen ambiente departamental."]}, {"n": "3.5", "t": "Sanciones", "l": ["La violación a la jerarquía y cadena de mando es una falta grave. Las sanciones pueden incluir amonestación, descenso de rango, suspensión o expulsión del departamento."]}]}, {"id": "dep-A-4", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 1: Disposiciones Generales", "num": "4", "titulo": "Requisitos para Permanecer en el Departamento", "tag": "", "intro": ["Para mantener la permanencia en cualquier departamento oficial, los miembros deben cumplir con los siguientes requisitos mínimos."], "subs": [{"n": "4.1", "t": "Requisitos Obligatorios", "l": ["Actividad Mínima: Cumplir con las horas de servicio establecidas por el departamento (patrullas, guardias, respuesta a emergencias, etc.).", "Calidad de Roleplay: Mantener un alto estándar de interpretación, profesionalismo y coherencia con el rol.", "Cumplimiento Normativo: Respetar la Normativa General y Departamental en todo momento.", "Evaluaciones: Aprobar las evaluaciones periódicas de conocimiento y desempeño realizadas por los superiores.", "Compromiso: Demostrar interés y dedicación al departamento."]}, {"n": "4.2", "t": "Conducta Requerida", "l": ["Mantener un historial limpio o con faltas menores.", "Participar activamente en entrenamientos y reuniones departamentales.", "Representar dignamente al departamento tanto dentro como fuera de servicio."]}, {"n": "4.3", "t": "Sanciones por Incumplimiento", "l": ["El incumplimiento reiterado de los requisitos para permanecer en el departamento puede resultar en:", "Amonestación verbal o escrita.", "Suspensión temporal.", "Descenso de rango.", "Expulsión definitiva del departamento."]}]}, {"id": "dep-A-5", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 2: Normas de Comportamiento", "num": "5", "titulo": "Uniformes y Apariencia", "tag": "", "intro": ["La imagen de los departamentos oficiales es fundamental para transmitir autoridad, profesionalismo y confianza a la ciudadanía."], "subs": [{"n": "5.1", "t": "Obligaciones", "l": ["Todo miembro debe usar el uniforme oficial completo y en buen estado mientras se encuentre en servicio.", "El uniforme debe llevarse de forma correcta (sin modificaciones no autorizadas).", "Se permite el uso de uniformes alternativos solo cuando el superior lo autorice."]}, {"n": "5.2", "t": "Apariencia Personal", "l": ["Mantener una apariencia limpia, ordenada y profesional (cortes de cabello adecuados, barba recortada si aplica, etc.).", "Prohibido el uso de accesorios exagerados, tatuajes visibles ofensivos o elementos que rompan la inmersión.", "La ropa civil fuera de servicio debe ser acorde con el rol y no dañar la imagen del departamento."]}, {"n": "5.3", "t": "Prohibiciones", "l": ["Modificar el uniforme oficial sin autorización.", "Usar uniformes incompletos o en mal estado.", "Llevar accesorios o ropa que no correspondan al departamento durante el servicio.", "Usar el uniforme fuera de servicio para obtener beneficios o intimidar."]}, {"n": "5.4", "t": "Sanciones", "l": ["El incumplimiento de las normas de uniformes y apariencia será sancionado según su gravedad, desde una amonestación hasta suspensión temporal del servicio."]}]}, {"id": "dep-A-6", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 2: Normas de Comportamiento", "num": "6", "titulo": "Uso de Vehículos Oficiales", "tag": "", "intro": ["Los vehículos oficiales son recursos del Estado y deben utilizarse exclusivamente para fines departamentales."], "subs": [{"n": "6.1", "t": "Uso Permitido", "l": ["Los vehículos solo podrán ser utilizados para cumplir con las funciones del departamento (patrullaje, respuesta a emergencias, traslados, etc.).", "Se debe conducir de forma responsable y respetando las normas de tránsito.", "Todo vehículo debe ser devuelto en buen estado al finalizar el servicio."]}, {"n": "6.2", "t": "Prohibiciones", "l": ["Usar vehículos oficiales para actividades personales o recreativas.", "Patrullar, buscar o conducir a mas de 100-120 KPH en intercepciones.", "Conducir en contra via. En caso de entrar por accidente debe de utilizar varandal de emergencia.", "Prestar vehículos oficiales a civiles sin autorización expresa.", "Conducir de forma temeraria o realizar maniobras peligrosas sin justificación RP.", "Modificar permanentemente los vehículos oficiales sin aprobación del Staff o superior.", "Abandonar vehículos oficiales en cualquier lugar sin motivo justificado."]}, {"n": "6.3", "t": "Responsabilidad", "l": ["Cada miembro es responsable del vehículo que utiliza. Cualquier daño causado por mal uso será reportado y podrá acarrear sanciones."]}, {"n": "6.4", "t": "Sanciones", "l": ["El mal uso de vehículos oficiales es una falta media a grave. Las sanciones pueden incluir amonestación, suspensión temporal del uso de vehículos o expulsión del departamento."]}]}, {"id": "dep-A-7", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 2: Normas de Comportamiento", "num": "7", "titulo": "Uso de Radio y Comunicación Oficial", "tag": "", "intro": ["La radio y los canales oficiales son herramientas fundamentales para la coordinación y seguridad de los departamentos."], "subs": [{"n": "7.1", "t": "Obligaciones", "l": ["Utilizar la radio de forma clara, breve y profesional.", "Usar los códigos y procedimientos establecidos por el departamento.", "Identificarse correctamente al hablar (ejemplo: Unidad 123 - Policía).", "Mantener los canales de radio libres para comunicaciones importantes."]}, {"n": "7.2", "t": "Prohibiciones", "l": ["Usar lenguaje vulgar, informal o bromas en canales oficiales.", "Spamear o saturar la radio con conversaciones innecesarias.", "Revelar información sensible o confidencial en canales abiertos.", "Discutir órdenes o quejas por radio frente a civiles."]}, {"n": "7.3", "t": "Principios Generales", "l": ["Una buena comunicación salva vidas y mejora la eficiencia del departamento.", "La radio debe usarse con disciplina y respeto."]}, {"n": "7.4", "t": "Sanciones", "l": ["El mal uso de la radio y canales oficiales es una falta media. Las sanciones pueden ir desde una amonestación hasta suspensión temporal, dependiendo de la gravedad y reiteración."]}]}, {"id": "dep-A-8", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 2: Normas de Comportamiento", "num": "8", "titulo": "Interacción con Civiles", "tag": "", "intro": ["Los miembros de los departamentos oficiales deben mantener una interacción respetuosa, profesional y justa con todos los civiles."], "subs": [{"n": "8.1", "t": "Principios Básicos", "l": ["Tratar a todos los civiles con respeto y cortesía, sin importar su rol o situación.", "Identificarse claramente al iniciar una interacción (ej: \"Policía Nacional...\").", "Explicar de forma clara y calmada el motivo de cualquier intervención.", "Priorizar el diálogo y la desescalada antes de recurrir a medidas coercitivas.", "es obligatoria la Lectura de derechos en caso de detencion."]}, {"n": "8.2", "t": "Prohibiciones", "l": ["Insultar, humillar o faltar el respeto a los civiles.", "Abusar de autoridad o usar la fuerza de forma innecesaria.", "Discriminar por raza, género, apariencia o cualquier otra condición.", "Ignorar solicitudes razonables de civiles o tratarlos de forma despectiva."]}, {"n": "8.3", "t": "Conducta Recomendada", "l": ["Mantener la calma en situaciones tensas.", "Ofrecer ayuda cuando sea posible y esté dentro de las funciones del departamento.", "Ser transparente en los procedimientos siempre que la seguridad lo permita."]}, {"n": "8.4", "t": "Sanciones", "l": ["La mala interacción con civiles es una falta media a grave. Las sanciones pueden ir desde una amonestación hasta suspensión o expulsión del departamento, especialmente en casos de abuso de autoridad."]}]}, {"id": "dep-A-9", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 2: Normas de Comportamiento", "num": "9", "titulo": "Abuso de Autoridad", "tag": "", "intro": ["El abuso de autoridad es una de las faltas más graves que puede cometer un miembro de un departamento oficial."], "subs": [{"n": "9.1", "t": "Definición", "l": ["Se considera abuso de autoridad cualquier uso indebido del poder, uniforme, insignia o posición para obtener beneficio personal, intimidar, humillar o perjudicar injustamente a otros jugadores."]}, {"n": "9.2", "t": "Ejemplos Prohibidos", "l": ["Usar la fuerza o amenazas sin justificación RP válida.", "Detener, multar o arrestar a civiles por motivos personales o venganza.", "Exigir favores, dinero o beneficios a cambio de no aplicar la ley.", "Humillar o insultar a civiles durante una intervención.", "Usar vehículos o equipamiento oficial para actividades no autorizadas."]}, {"n": "9.3", "t": "Principios Generales", "l": ["La autoridad otorgada por el departamento debe usarse exclusivamente para servir y proteger a la comunidad.", "Cualquier acción que dañe la confianza de los ciudadanos en las instituciones será sancionada con severidad."]}, {"n": "9.4", "t": "Sanciones", "l": ["El abuso de autoridad es una falta muy grave. Las sanciones habituales incluyen suspensión inmediata, descenso de rango o expulsión definitiva del departamento y posible sanción general en el servidor."]}]}, {"id": "dep-A-10", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 3: Procedimientos Operativos", "num": "10", "titulo": "Uso de la Fuerza y Armas", "tag": "", "intro": ["El uso de la fuerza y armas por parte de los departamentos oficiales debe seguir un principio estricto de escalada progresiva."], "subs": [{"n": "10.1", "t": "Principio de Escalada", "l": ["Todo miembro debe utilizar el mínimo nivel de fuerza necesario para resolver una situación. La fuerza debe aumentar solo cuando sea estrictamente necesario."]}, {"n": "10.2", "t": "Niveles de Fuerza", "l": ["Presencia — Presencia verbal y visual.", "Verbal — Órdenes claras y firmes.", "Fuerza física — Llaves, esposas, técnicas de control.", "Taser / Spray — Armas no letales.", "Armas letales — Solo como último recurso cuando existe peligro inminente de muerte o lesiones graves."]}, {"n": "10.3", "t": "Obligaciones", "l": ["Intentar siempre la resolución pacífica primero.", "Dar advertencias claras antes de usar fuerza.", "Documentar el uso de fuerza en reportes posteriores.", "Respetar el FearRP de los civiles."]}, {"n": "10.4", "t": "Prohibiciones", "l": ["Usar fuerza excesiva o desproporcionada.", "Sacar arma de fuego sin motivo justificado.", "Disparar a personas que huyen sin representar peligro inminente.", "Usar armas letales como primera opción."]}, {"n": "10.5", "t": "Sanciones", "l": ["El uso indebido de la fuerza es una falta grave. Las sanciones pueden ir desde suspensión hasta expulsión definitiva del departamento."]}]}, {"id": "dep-A-11", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 3: Procedimientos Operativos", "num": "11", "titulo": "Procedimientos de Detención y Arresto", "tag": "", "intro": ["Los procedimientos de detención y arresto deben realizarse de forma legal, segura y respetuosa."], "subs": [{"n": "11.1", "t": "Requisitos para Detener", "l": ["Solo se puede detener a un civil cuando exista una causa probable o flagrancia de delito.", "Se debe identificar claramente como autoridad antes de proceder.", "Informar al civil el motivo de la detención de forma clara y calmada."]}, {"n": "11.2", "t": "Procedimiento Estándar", "l": ["Orden verbal clara (“¡Policía Nacional, deténgase!”).", "Uso de esposas cuando sea necesario y seguro.", "Registro legal del detenido (si aplica).", "Traslado a la comisaría para el proceso correspondiente.", "Leer los derechos al detenido cuando sea arrestado formalmente."]}, {"n": "11.3", "t": "Prohibiciones", "l": ["Detener sin motivo válido (detención arbitraria).", "Usar fuerza excesiva durante la detención.", "Humillar o insultar al detenido.", "Realizar registros sin justificación legal."]}, {"n": "11.4", "t": "Principios Generales", "l": ["Todo procedimiento debe respetar los derechos del ciudadano y seguir la ley del estado de Liberty County.", "La profesionalidad durante las detenciones refuerza la confianza de la comunidad."]}, {"n": "11.5", "t": "Sanciones", "l": ["Incumplir los procedimientos de detención y arresto es una falta grave. Las sanciones pueden incluir suspensión temporal o expulsión del departamento."]}]}, {"id": "dep-A-12", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 3: Procedimientos Operativos", "num": "12", "titulo": "Persecuciones Vehiculares", "tag": "", "intro": ["Las persecuciones vehiculares son maniobras de alto riesgo que deben realizarse con responsabilidad y siguiendo protocolos claros."], "subs": [{"n": "12.1", "t": "Condiciones para Iniciar una Persecución", "l": ["Solo se iniciará cuando exista una causa grave (delito en curso, huida tras detención, peligro para la ciudadanía, etc.).", "Se debe evaluar el riesgo para civiles antes de iniciar la persecución.", "Informar por radio el inicio de la persecución (ubicación, vehículo, motivo)."]}, {"n": "12.2", "t": "Reglas Durante la Persecución", "l": ["Mantener distancia segura y evitar maniobras temerarias.", "Priorizar la seguridad de civiles y peatones en todo momento.", "Coordinarse correctamente con otras unidades.", "No se permite el uso excesivo de fuerza (PIT, bloqueos peligrosos) sin autorización o necesidad extrema."]}, {"n": "12.3", "t": "Finalización de la Persecución", "l": ["Se debe finalizar la persecución si representa un peligro desproporcionado para la ciudadanía.", "Una vez detenido el sospechoso, aplicar los procedimientos de detención estándar."]}, {"n": "12.4", "t": "Prohibiciones", "l": ["Iniciar persecuciones por faltas menores.", "Conducir de forma suicida o poner en riesgo innecesario a civiles.", "Usar helicópteros o unidades especiales sin coordinación."]}, {"n": "12.5", "t": "Sanciones", "l": ["El mal manejo de persecuciones vehiculares es una falta grave.", "Las sanciones pueden incluir suspensión temporal o expulsión del departamento."]}]}, {"id": "dep-A-13", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 3: Procedimientos Operativos", "num": "13", "titulo": "Uso de Taser y Equipo No Letal", "tag": "", "intro": ["El uso de equipo no letal (Taser, spray de pimienta, bastón, etc.) es una herramienta intermedia en la escalada de fuerza."], "subs": [{"n": "13.1", "t": "Condiciones de Uso", "l": ["Solo se usará cuando el sujeto represente una amenaza física moderada y no haya respondido a órdenes verbales.", "Debe intentarse siempre la desescalada verbal antes de usar equipo no letal.", "El Taser solo se utilizará cuando exista riesgo inminente de agresión física."]}, {"n": "13.2", "t": "Reglas de Uso", "l": ["Apuntar correctamente y dar advertencia cuando sea posible (“¡Taser, Taser!”).", "No se debe usar el Taser de forma punitiva o por frustración.", "Después de usar el Taser, se debe prestar atención médica al sujeto.", "Registrar el uso del equipo no letal en el informe correspondiente."]}, {"n": "13.3", "t": "Prohibiciones", "l": ["Usar el Taser en personas que no representen amenaza física.", "Disparar el Taser a la cabeza, cuello o genitales sin necesidad extrema.", "Usar equipo no letal como método de tortura o castigo.", "Usarlo de forma excesiva o repetida sin justificación."]}, {"n": "13.4", "t": "Sanciones", "l": ["El mal uso de Taser y equipo no letal es una falta grave. Las sanciones pueden ir desde suspensión temporal hasta expulsión del departamento."]}]}, {"id": "dep-A-14", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 3: Procedimientos Operativos", "num": "14", "titulo": "Procedimientos en Escenas de Emergencia", "tag": "", "intro": ["Los procedimientos en escenas de emergencia deben priorizar la vida humana, la coordinación y la profesionalidad."], "subs": [{"n": "14.1", "t": "Principios Generales", "l": ["La prioridad principal es salvar vidas y estabilizar a los heridos.", "Coordinarse siempre con los demás departamentos (Policía, EMS, Bomberos).", "Mantener la calma y actuar de forma organizada bajo presión.", "Respetar la escena y no contaminar evidencia cuando corresponda."]}, {"n": "14.2", "t": "Obligaciones", "l": ["Llegar a la escena lo más rápido posible sin poner en riesgo innecesario.", "Evaluar la situación y solicitar refuerzos si es necesario.", "Proporcionar primeros auxilios y estabilización a los heridos.", "Mantener comunicación constante por radio con el centro de control."]}, {"n": "14.3", "t": "Prohibiciones", "l": ["Interferir en procedimientos policiales sin motivo justificado.", "Mover cuerpos o evidencia sin autorización en escenas criminales.", "Publicar o filtrar información sensible de la escena.", "Actuar de forma individual sin coordinación con el equipo."]}, {"n": "14.4", "t": "Sanciones", "l": ["El incumplimiento de los procedimientos en escenas de emergencia es una falta media a grave. Las sanciones pueden ir desde amonestación hasta suspensión o expulsión del departamento."]}]}, {"id": "dep-A-anexo", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 4: Normas Administrativas", "num": "Anexo", "titulo": "Rol de Corruccion", "tag": "", "intro": ["El rol de corrupción permite explorar mecánicas de sobornos, influencias y abuso de poder dentro de un marco realista e inmersivo."], "subs": [{"n": "", "t": "Definición", "l": ["El rol de corrupción es la interacción RP donde un personaje con autoridad (funcionario, policía, etc.) abusa de su posición a cambio de beneficios personales."]}, {"n": "", "t": "Requisitos", "l": ["Debe existir una interacción RP clara y progresiva.", "Ambas partes (corruptor y corrupto) deben estar de acuerdo con la escena.", "El rol debe ser discreto y coherente con la personalidad de los personajes.", "No se permite corrupción masiva o abierta que afecte gravemente el balance del servidor."]}, {"n": "", "t": "Prohibiciones", "l": ["Corromper o aceptar sobornos sin justificación RP o de forma gratuita.", "Usar la corrupción para hacer FailRP, Powergaming o favorecer amigos OOC.", "Corromper a personajes nuevos o sin experiencia.", "Hacer público o alardear de actos de corrupción sin motivo RP.", "Maximo de 2 funcionarios corruptos por departamento"]}, {"n": "", "t": "Sanciones", "l": ["El mal uso del rol de corrupción es una falta grave. Las sanciones pueden ir desde suspensión temporal hasta expulsión permanente, especialmente si afecta la experiencia general del servidor."]}]}, {"id": "dep-A-15", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 4: Normas Administrativas", "num": "15", "titulo": "Reportes y Documentación", "tag": "", "intro": ["La documentación correcta es esencial para el buen funcionamiento y la transparencia de los departamentos oficiales."], "subs": [{"n": "15.1", "t": "Obligaciones", "l": ["Todo miembro debe redactar reportes claros, objetivos y completos de las intervenciones realizadas.", "Los reportes deben incluir: hora, lugar, personas involucradas, descripción de los hechos y acciones tomadas.", "Entregar los reportes en el tiempo establecido por el departamento.", "Mantener la confidencialidad de la información sensible."]}, {"n": "15.2", "t": "Normas de Redacción", "l": ["Utilizar lenguaje formal, claro y profesional.", "Evitar opiniones personales o juicios de valor.", "Ser objetivo y basarse en hechos.", "Corregir errores antes de entregar el reporte."]}, {"n": "15.3", "t": "Prohibiciones", "l": ["Falsificar, omitir o alterar información en los reportes.", "Compartir reportes confidenciales con civiles o en canales no oficiales.", "No entregar reportes sin justificación válida."]}, {"n": "15.4", "t": "Sanciones", "l": ["El incumplimiento de las normas de reportes y documentación es una falta media. La falsificación de documentos es una falta grave y puede resultar en expulsión del departamento."]}]}, {"id": "dep-A-16", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 4: Normas Administrativas", "num": "16", "titulo": "Actividad Mínima y Compromiso", "tag": "", "intro": ["La permanencia en un departamento oficial requiere un compromiso real y actividad constante."], "subs": [{"n": "16.1", "t": "Actividad Mínima", "l": ["Cada miembro debe cumplir con el mínimo de horas de servicio establecido por su departamento (patrullas, guardias, respuesta a llamadas, etc.).", "La actividad se medirá semanal o mensualmente según lo determine la administración.", "Se debe notificar con antelación en caso de inactividad prolongada."]}, {"n": "16.2", "t": "Compromiso", "l": ["Participar activamente en entrenamientos, reuniones y operaciones departamentales.", "Mantener una actitud positiva y proactiva dentro del departamento.", "Contribuir al crecimiento y mejora continua del departamento."]}, {"n": "16.3", "t": "Excepciones", "l": ["En caso de ausencia justificada (problemas personales, estudios, trabajo), se debe notificar al superior con anticipación.", "El Staff evaluará cada caso de forma individual."]}, {"n": "16.4", "t": "Sanciones", "l": ["El incumplimiento reiterado de la actividad mínima y el compromiso es causa de expulsión del departamento. Se aplicarán sanciones progresivas: advertencia → suspensión → expulsión."]}]}, {"id": "dep-A-17", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 4: Normas Administrativas", "num": "17", "titulo": "Sistema de Ascensos y Rangos", "tag": "", "intro": ["El sistema de ascensos busca reconocer el esfuerzo, dedicación y calidad de los miembros de los departamentos oficiales."], "subs": [{"n": "17.1", "t": "Principios del Sistema", "l": ["Los ascensos se basan en mérito, no en amistad o antigüedad sola.", "Se valoran: actividad, calidad de roleplay, liderazgo, responsabilidad y respeto a las normas.", "Todo ascenso debe ser aprobado por los superiores y/o el Staff."]}, {"n": "17.2", "t": "Requisitos Generales", "l": ["Cumplir con el tiempo mínimo en el rango actual.", "Demostrar madurez y buen comportamiento.", "Aprobar evaluaciones de conocimiento y desempeño.", "Contar con recomendaciones de superiores.", "Permanencia minima de dos (2) semanas en el mismo puesto, cargo o rango."]}, {"n": "17.3", "t": "Prohibiciones", "l": ["Solicitar ascensos de forma insistente o inapropiada.", "Presionar a superiores para obtener un ascenso.", "Otorgar ascensos por favoritismo o sin justificación."]}, {"n": "17.4", "t": "Procedimiento", "l": ["Los ascensos se evaluarán de forma periódica.", "El miembro podrá ser notificado de sus fortalezas y áreas de mejora.", "Los ascensos se anunciarán de forma oficial."]}, {"n": "17.5", "t": "Sanciones", "l": ["Manipular o faltar el respeto al sistema de ascensos es una falta grave. Esto puede resultar en congelamiento de ascensos o sanciones disciplinarias."]}]}, {"id": "dep-A-18", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 4: Normas Administrativas", "num": "18", "titulo": "Sanciones Internas y Expulsión del Departamento", "tag": "", "intro": ["Las sanciones internas buscan corregir conductas inadecuadas y mantener el orden y la calidad dentro de los departamentos."], "subs": [{"n": "18.1", "t": "Tipos de Sanciones", "l": ["Amonestación (verbal o escrita)", "Suspensión temporal (de días a semanas)", "Descenso de rango", "Expulsión definitiva del departamento"]}, {"n": "18.2", "t": "Causas de Sanciones", "l": ["Incumplimiento reiterado de la normativa departamental.", "Abuso de autoridad o mal uso de la fuerza.", "Baja actividad o falta de compromiso.", "Insubordinación grave.", "Conducta que dañe la imagen del departamento."]}, {"n": "18.3", "t": "Procedimiento", "l": ["Toda sanción debe estar justificada y documentada.", "El miembro tendrá derecho a presentar sus descargos antes de una sanción grave.", "Las expulsiones definitivas serán decididas por el alto mando o Staff."]}, {"n": "18.4", "t": "Expulsión del Departamento", "l": ["La expulsión es la medida más grave y se aplica en casos de faltas muy graves o reiteradas.", "Una vez expulsado, el miembro no podrá reingresar al mismo departamento sin autorización especial del Staff."]}, {"n": "18.5", "t": "Principios Generales", "l": ["Las sanciones buscan corregir, no solo castigar. Se aplicarán de forma justa y proporcional a la falta cometida."]}]}, {"id": "dep-A-19", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 5: Disposiciones Finales", "num": "19", "titulo": "Reformas y Actualizaciones", "tag": "", "intro": ["La presente normativa es un documento vivo y puede ser modificado para adaptarse a las necesidades del servidor."], "subs": [{"n": "19.1", "t": "Autoridad para Reformar", "l": ["Solo la Administración departamental y los Jefes Superiores de cada departamento tienen la facultad de proponer y aprobar reformas.", "Todas las modificaciones deben ser notificadas a los miembros de los departamentos."]}, {"n": "19.2", "t": "Procedimiento de Actualización", "l": ["Las propuestas de cambio deben ser presentadas por escrito con justificación.", "Se evaluará el impacto de la reforma antes de su aprobación.", "Las actualizaciones serán publicadas con fecha y número de versión.", "Los miembros tendrán un período de adaptación razonable tras cada cambio importante."]}, {"n": "19.3", "t": "Principios Generales", "l": ["Las reformas buscan mejorar el funcionamiento, la calidad y la experiencia de los departamentos.", "Se priorizará siempre la claridad, la justicia y el equilibrio entre todos los jugadores."]}, {"n": "19.4", "t": "Vigencia", "l": ["Esta normativa entra en vigencia a partir de su publicación. La versión más reciente será la única válida."]}]}, {"id": "dep-A-20", "sec": "dep", "bloque": "A", "bloqueT": "Normativa para Departamentos Primerios", "cap": "Capítulo 5: Disposiciones Finales", "num": "20", "titulo": "Aclaraciones e Interpretación", "tag": "", "intro": ["Esta normativa busca ser clara y de fácil comprensión. Cualquier duda sobre su aplicación se resolverá de acuerdo a los siguientes criterios."], "subs": [{"n": "20.1", "t": "Interpretación", "l": ["La interpretación final de esta normativa corresponde al Staff General y a los Jefes Superiores de cada departamento.", "En caso de ambigüedad, se aplicará el sentido que mejor se ajuste al espíritu de la norma y al beneficio del roleplay.", "Las decisiones del Staff son definitivas en cuanto a la interpretación."]}, {"n": "20.2", "t": "Aclaraciones", "l": ["Cualquier miembro puede solicitar aclaración sobre un artículo mediante ticket o canal correspondiente.", "Las aclaraciones oficiales serán publicadas para conocimiento de todos los miembros.", "Las aclaraciones tienen el mismo valor que la normativa."]}, {"n": "20.3", "t": "Disposiciones Finales", "l": ["Esta normativa es de obligatorio cumplimiento para todos los miembros de los departamentos oficiales.", "La ignorancia de la normativa no exime de responsabilidad.", "La administración se reserva el derecho de modificar esta normativa cuando lo considere necesario."]}]}, {"id": "dep-B-1", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 1: Disposiciones Generales", "num": "1", "titulo": "Principios y Valores", "tag": "", "intro": ["Los departamentos secundarios (EMS, Bomberos y Tránsito [DOT]) tienen como misión principal salvar vidas, proteger bienes y mantener el orden en la movilidad y seguridad vial."], "subs": [{"n": "1.1", "t": "Valores Fundamentales", "l": ["Los miembros de estos departamentos deben regirse siempre por los siguientes valores:", "Servicio desinteresado a la comunidad: Priorizar el bienestar de los ciudadanos por encima de cualquier interés personal.", "Profesionalismo: Actuar con ética, responsabilidad y competencia en todo momento.", "Trabajo en equipo: Colaborar de forma coordinada con otros departamentos y compañeros.", "Respeto a la vida humana: Proteger y valorar la vida de todas las personas sin excepción."]}, {"n": "1.2", "t": "Aplicación de los Valores", "l": ["Estos principios deben reflejarse en cada acción y decisión durante el servicio.", "El incumplimiento de estos valores fundamentales afectará directamente la permanencia del miembro en el departamento."]}, {"n": "1.3", "t": "Sanciones", "l": ["La falta grave o reiterada a los principios y valores establecidos podrá resultar en:", "Amonestación", "Suspensión temporal", "Expulsión definitiva del departamento"]}]}, {"id": "dep-B-2", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 1: Disposiciones Generales", "num": "2", "titulo": "Código de Conducta", "tag": "", "intro": ["Los miembros de los departamentos secundarios deben cumplir en todo momento con un alto estándar de conducta."], "subs": [{"n": "2.1", "t": "Principios de Conducta", "l": ["Actuar siempre con ética y empatía hacia los ciudadanos y compañeros.", "Mantener la calma en situaciones de alta presión o estrés.", "No discriminar ni tratar de forma desigual a ningún ciudadano por cualquier motivo.", "Prohibido el abuso de autoridad o el uso indebido de recursos del departamento."]}, {"n": "2.2", "t": "Aplicación", "l": ["Estos principios aplican tanto en servicio como fuera de él cuando se represente al departamento.", "El comportamiento debe reflejar profesionalismo en todo momento."]}, {"n": "2.3", "t": "Sanciones", "l": ["El incumplimiento del Código de Conducta será sancionado según la gravedad:", "Falta leve: Amonestación", "Falta media: Suspensión temporal", "Falta grave: Expulsión del departamento e incluso del servidor"]}]}, {"id": "dep-B-3", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 1: Disposiciones Generales", "num": "3", "titulo": "Requisitos para Permanecer en el Departamento", "tag": "", "intro": ["Para mantenerse activo dentro de los departamentos secundarios, los miembros deben cumplir con los siguientes requisitos:"], "subs": [{"n": "3.1", "t": "Requisitos Obligatorios", "l": ["Cumplir con la actividad mínima establecida por el departamento.", "Aprobar las evaluaciones periódicas de conocimiento y roleplay.", "Mantener un historial limpio sin sanciones graves."]}, {"n": "3.2", "t": "Evaluación Continua", "l": ["Los miembros serán evaluados de forma regular en cuanto a:", "Asistencia y actividad en servicio", "Calidad del roleplay", "Conocimiento de procedimientos", "Cumplimiento de los valores y código de conducta"]}, {"n": "3.3", "t": "Sanciones por Incumplimiento", "l": ["El no cumplir con estos requisitos podrá resultar en:", "Amonestación", "Suspensión temporal", "Expulsión definitiva del departamento"]}]}, {"id": "dep-B-4", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 2: Normas Operativas", "num": "4", "titulo": "Uniformes y Apariencia", "tag": "", "intro": ["Los miembros de los departamentos secundarios deben mantener una imagen profesional en todo momento."], "subs": [{"n": "4.1", "t": "Uniformes", "l": ["Se debe usar el uniforme oficial completo y en buen estado durante el servicio.", "Está prohibido modificar uniformes sin autorización expresa del Staff o liderazgo del departamento.", "El uniforme debe estar limpio y correctamente colocado."]}, {"n": "4.2", "t": "Apariencia Personal", "l": ["La apariencia del personaje debe ser profesional y acorde al rol.", "Se prohíben tatuajes visibles excesivos, peinados extravagantes o accesorios que rompan la inmersión.", "La vestimenta civil fuera de servicio debe mantener un nivel de decoro adecuado."]}, {"n": "4.3", "t": "Sanciones", "l": ["El incumplimiento de las normas de uniformes y apariencia será sancionado"]}]}, {"id": "dep-B-5", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 2: Normas Operativas", "num": "5", "titulo": "Uso de Vehículos Oficiales", "tag": "", "intro": ["Los vehículos oficiales son recursos del departamento y deben ser utilizados exclusivamente para el cumplimiento de funciones oficiales."], "subs": [{"n": "5.1", "t": "Uso Permitido", "l": ["Los vehículos solo podrán ser utilizados para actividades relacionadas con el servicio (atención de emergencias, patrullaje, traslados médicos, respuesta a incidentes, etc.).", "Se debe conducir con responsabilidad, prudencia y respetando todas las normas de tránsito vigentes.", "Todo daño, avería o problema mecánico debe ser reportado inmediatamente al superior o al Staff.", "El uso de sirenas y luces debe limitarse a situaciones que lo justifiquen según los protocolos."]}, {"n": "5.2", "t": "Prohibiciones", "l": ["Está estrictamente prohibido el uso recreativo, personal o para beneficio propio de los vehículos oficiales.", "No se permite utilizar los vehículos para actividades fuera de servicio o sin autorización.", "Se prohíbe realizar maniobras peligrosas, carreras o conducción temeraria.", "No se permite prestar vehículos oficiales a civiles ni a miembros de otros departamentos sin autorización."]}, {"n": "5.3", "t": "Sanciones", "l": ["Falta leve: Amonestación verbal o escrita.", "Falta media o reiterada: Suspensión temporal del servicio (de 3 a 15 días).", "Falta grave: Expulsión definitiva del departamento y posible sanción adicional según la gravedad."]}]}, {"id": "dep-B-6", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 2: Normas Operativas", "num": "6", "titulo": "Procedimientos en Escenas", "tag": "", "intro": ["Los miembros de los departamentos secundarios deben actuar con profesionalismo y coordinación durante cualquier escena o incidente."], "subs": [{"n": "6.1", "t": "Prioridades en Escenas", "l": ["Priorizar siempre la vida de los heridos y civiles presentes en la escena.", "Brindar atención médica o asistencia inmediata a las personas que lo requieran.", "Mantener la calma y actuar de forma organizada bajo presión."]}, {"n": "6.2", "t": "Coordinación con Otros Departamentos", "l": ["Coordinarse correctamente con la Policía en escenas donde se requiera seguridad o apoyo.", "No interferir en procedimientos policiales sin motivo justificado o sin autorización.", "Mantener comunicación clara y constante con los demás departamentos involucrados."]}, {"n": "6.3", "t": "Sanciones", "l": ["Falta leve: Amonestación.", "Falta media o reiterada: Suspensión temporal del servicio.", "Falta grave: Expulsión definitiva del departamento."]}]}, {"id": "dep-B-7", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 2: Normas Operativas", "num": "7", "titulo": "Comunicación y Radio", "tag": "", "intro": ["La comunicación a través de radio es una herramienta fundamental para la coordinación entre departamentos."], "subs": [{"n": "7.1", "t": "Normas de Comunicación", "l": ["Usar los canales de radio de forma clara, breve y profesional en todo momento.", "Identificarse correctamente antes de transmitir (ejemplo: “EMS-12 a Central”).", "Mantener mensajes cortos y concretos para no saturar los canales.", "Utilizar códigos y terminología oficial cuando corresponda."]}, {"n": "7.2", "t": "Prohibiciones", "l": ["Está prohibido el uso de lenguaje vulgar, informal, slang o bromas en canales de radio oficiales.", "No se permite saturar los canales con conversaciones innecesarias.", "Queda prohibido transmitir información OOC a través de la radio."]}]}, {"id": "dep-B-8", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 3: Normas Específicas por Departamento", "num": "8", "titulo": "EMS (Emergencias Médicas)", "tag": "", "intro": ["El departamento de EMS es responsable de la atención prehospitalaria y salvamento de vidas."], "subs": [{"n": "8.1", "t": "Principios Básicos", "l": ["El EMS debe priorizar siempre la atención médica y estabilización de los pacientes.", "Toda actuación debe realizarse con profesionalismo, rapidez y respeto a la vida humana.", "La prioridad es salvar vidas y reducir el sufrimiento de los heridos."]}, {"n": "8.2", "t": "Reglas Específicas", "l": ["Está prohibido revivir personas en situaciones de muerte confirmada sin una justificación RP clara y realista.", "Se debe mantener la confidencialidad absoluta de toda información médica de los pacientes.", "Los procedimientos médicos deben ser roleados de forma coherente con el conocimiento realista de un paramédico.", "No se permite diagnosticar o tratar de forma irrealista o exagerada (godmoding médico)."]}, {"n": "8.3", "t": "Coordinación", "l": ["El EMS debe coordinarse correctamente con la Policía en escenas de alto riesgo.", "Se debe solicitar apoyo policial cuando la seguridad del equipo médico esté comprometida.", "La comunicación por radio debe ser clara, breve y profesional."]}, {"n": "8.4", "t": "Sanciones", "l": ["Falta leve: Amonestación.", "Falta media o reiterada: Suspensión temporal del servicio.", "Falta grave (como revivir sin justificación o romper confidencialidad): Expulsión definitiva del departamento."]}]}, {"id": "dep-B-9", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 3: Normas Específicas por Departamento", "num": "9", "titulo": "Bomberos", "tag": "", "intro": ["El departamento de Bomberos es responsable de la extinción de incendios, rescates y protección contra situaciones de emergencia relacionadas con fuego y estructuras."], "subs": [{"n": "9.1", "t": "Principios Básicos", "l": ["Los bomberos deben priorizar siempre la extinción de incendios y el rescate de personas en peligro. La seguridad del equipo y de los civiles es la máxima prioridad en toda intervención. Se debe actuar con rapidez, pero siempre manteniendo la precaución necesaria."]}, {"n": "9.2", "t": "Reglas Específicas", "l": ["Actuar con precaución en escenas con peligro estructural o riesgo de colapso.", "Coordinarse correctamente con la Policía en casos de incendios provocados o sospechosos.", "Realizar búsquedas y rescates de forma metódica y segura.", "Mantener la profesionalidad en todo momento durante las intervenciones."]}, {"n": "9.3", "t": "Sanciones", "l": ["Falta leve: Amonestación.", "Falta media o reiterada: Suspensión temporal del servicio.", "Falta grave (negligencia que ponga en riesgo vidas o falta de coordinación): Expulsión definitiva del departamento."]}]}, {"id": "dep-B-10", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 3: Normas Específicas por Departamento", "num": "10", "titulo": "DOT (Departamento de Transporte)", "tag": "", "intro": ["El Departamento de Transporte (DOT) es responsable de la seguridad vial, el orden en las vías y la gestión del tráfico en Liberty County."], "subs": [{"n": "10.1", "t": "Principios Básicos", "l": ["El DOT debe velar por el orden y la seguridad vial en todo momento. Su función principal es prevenir accidentes y garantizar el correcto flujo vehicular. Todas las acciones deben realizarse con profesionalismo y respeto hacia los ciudadanos."]}, {"n": "10.2", "t": "Funciones Principales", "l": ["Realizar controles de velocidad y aplicar multas de forma justa y siempre con justificación RP.", "Participar en la gestión y control del tráfico durante emergencias o eventos especiales.", "Atender accidentes de tránsito y colaborar con EMS y Policía cuando sea necesario.", "Realizar patrullaje preventivo en zonas de alto riesgo vial."]}, {"n": "10.3", "t": "Sanciones", "l": ["Falta leve: Amonestación.", "Falta media o reiterada: Suspensión temporal del servicio.", "Falta grave (abuso de autoridad, multas injustificadas o negligencia): Expulsión definitiva del departamento."]}]}, {"id": "dep-B-11", "sec": "dep", "bloque": "B", "bloqueT": "Normativa para Departamentos Secundarios", "cap": "Capítulo 4: Sanciones", "num": "11", "titulo": "Sanciones Internas", "tag": "", "intro": ["Las sanciones internas son medidas disciplinarias aplicadas por el liderazgo o el Staff a los miembros de los departamentos secundarios."], "subs": [{"n": "11.1", "t": "Clasificación de Faltas", "l": ["Las faltas se clasificarán en tres categorías según su gravedad:", "Falta Leve: Incumplimientos menores de normas o procedimientos.", "Falta Grave: Incumplimientos que afectan la imagen del departamento o ponen en riesgo la operación.", "Falta Muy Grave: Violaciones graves de los valores, código de conducta o que comprometan vidas."]}, {"n": "11.2", "t": "Tipos de Sanciones", "l": ["Las sanciones pueden incluir:", "Amonestación verbal o escrita.", "Suspensión temporal del servicio.", "Descenso de rango.", "Expulsión definitiva del departamento."]}, {"n": "11.3", "t": "Aplicación de Sanciones", "l": ["La sanción se aplicará de forma proporcional a la gravedad de la falta y considerando antecedentes del miembro. Todas las sanciones serán notificadas por escrito al interesado."]}]}, {"id": "dep-C-1", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 1: Disposiciones Generales", "num": "1", "titulo": "Principios Básicos", "tag": "", "intro": ["Los negocios y locales civiles son parte fundamental de la economía y el roleplay cotidiano."], "subs": [{"n": "1.1", "t": "Objetivo Principal", "l": ["Su operación debe ser realista, legal y contribuir a una mejor experiencia para todos los jugadores.", "Los negocios deben enriquecer la vida civil y generar interacciones RP de calidad."]}, {"n": "1.2", "t": "Principios Generales", "l": ["Operar de forma honesta y legal dentro del marco del servidor.", "Mantener un roleplay coherente con el tipo de negocio y su ubicación.", "Respetar a los clientes y empleados en todo momento.", "Contribuir positivamente a la economía y la comunidad del servidor."]}, {"n": "1.3", "t": "Sanciones", "l": ["El incumplimiento de estos principios podrá resultar en:", "Amonestación.", "Suspensión temporal del negocio.", "Cierre definitivo del local en casos graves."]}]}, {"id": "dep-C-2", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 1: Disposiciones Generales", "num": "2", "titulo": "Registro de Negocios", "tag": "", "intro": ["Todo negocio o local civil debe estar debidamente registrado ante la administración del servidor."], "subs": [{"n": "2.1", "t": "Requisitos de Registro", "l": ["Todo jugador que desee abrir un negocio debe presentar una solicitud formal.", "La solicitud debe incluir: nombre del negocio, tipo de actividad, ubicación y backstory breve.", "Solo se aprobarán negocios realistas y coherentes con el universo de Liberty County.", "El registro es obligatorio antes de comenzar cualquier actividad comercial RP."]}, {"n": "2.2", "t": "Obligaciones tras el Registro", "l": ["Mantener el negocio activo y con roleplay regular.", "Cumplir con las leyes y normativas del servidor.", "Actualizar la información del negocio cuando haya cambios importantes."]}, {"n": "2.3", "t": "Sanciones", "l": ["Operar un negocio sin registro: Suspensión temporal o cierre inmediato.", "Incumplimiento reiterado de las normas: Cierre definitivo del negocio y posibles sanciones al propietario."]}]}, {"id": "dep-C-3", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 1: Disposiciones Generales", "num": "3", "titulo": "Propiedad y Responsabilidad", "tag": "", "intro": ["Los dueños de negocios y locales civiles son plenamente responsables de su propiedad y de lo que ocurra en ella."], "subs": [{"n": "3.1", "t": "Responsabilidades del Propietario", "l": ["El propietario es responsable de mantener el local en buen estado y con roleplay coherente.", "Debe velar por la seguridad y el buen trato hacia los clientes y empleados dentro de su propiedad.", "Es obligación del dueño resolver conflictos que ocurran dentro de su negocio de forma RP.", "Debe reportar cualquier actividad ilegal o sospechosa que ocurra en su local."]}, {"n": "3.2", "t": "Derechos del Propietario", "l": ["Tiene derecho a negar la entrada a personas que alteren el orden o incumplan las normas.", "Puede establecer reglas internas siempre que no contradigan las normas del servidor.", "Es responsable de proteger su propiedad contra robos o daños mediante roleplay."]}]}, {"id": "dep-C-4", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 2: Normas de Operacion", "num": "4", "titulo": "Horarios y Actividad", "tag": "", "intro": ["Los negocios y locales civiles deben mantener horarios y actividad coherentes con su tipo de establecimiento."], "subs": [{"n": "4.1", "t": "Horarios de Operación", "l": ["Los negocios deben establecer horarios de apertura y cierre realistas.", "Se recomienda mantener el negocio abierto al menos varias horas al día para generar roleplay.", "Los horarios deben ser anunciados claramente a los clientes (carteles, mensajes, etc.)."]}, {"n": "4.2", "t": "Actividad Obligatoria", "l": ["Se debe mantener actividad RP regular dentro del local.", "El abandono prolongado del negocio sin justificación puede llevar a la revocación de la propiedad.", "Los dueños son responsables de asegurar que el negocio no quede inactivo por largos períodos."]}]}, {"id": "dep-C-5", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 2: Normas de Operacion", "num": "5", "titulo": "Rol de Empleados", "tag": "", "intro": ["Los empleados son una parte fundamental en la operación y el roleplay de los negocios y locales civiles."], "subs": [{"n": "5.1", "t": "Obligaciones de los Empleados", "l": ["Los empleados deben actuar de forma profesional y acorde al tipo de negocio.", "Se debe mantener una actitud respetuosa y servicial hacia los clientes.", "Cumplir con las instrucciones del propietario o gerente del local.", "Realizar sus labores de forma coherente y realista."]}, {"n": "5.2", "t": "Obligaciones del Propietario", "l": ["El propietario es responsable de capacitar y supervisar a sus empleados.", "Debe asegurarse de que los empleados mantengan un buen roleplay.", "Puede contratar y despedir empleados según las necesidades del negocio (siempre con justificación RP)."]}, {"n": "5.3", "t": "Sanciones", "l": ["Mal comportamiento o bajo roleplay por parte de empleados: Amonestación al empleado y al propietario.", "Reiteración de malas prácticas: Suspensión temporal del negocio.", "Casos graves (toxicidad o abuso): Cierre temporal o definitivo del local."]}]}, {"id": "dep-C-6", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 2: Normas de Operacion", "num": "6", "titulo": "Precios y Economía", "tag": "", "intro": ["Los precios y la economía de los negocios deben ser realistas y coherentes con el universo de Liberty County."], "subs": [{"n": "6.1", "t": "Establecimiento de Precios", "l": ["Los precios deben ser justos y acordes al tipo de producto o servicio ofrecido.", "Se recomienda establecer precios realistas según la economía del servidor.", "Los precios deben ser anunciados claramente a los clientes."]}, {"n": "6.2", "t": "Reglas Económicas", "l": ["No se permite inflar precios de forma abusiva o irrealista.", "Está prohibido el cobro de precios excesivos que rompan la inmersión.", "Los negocios deben contribuir a una economía equilibrada y justa para todos los jugadores."]}, {"n": "6.3", "t": "Sanciones", "l": ["Precios abusivos o irrealistas: Amonestación y obligación de ajustar precios.", "Reiteración o explotación económica: Suspensión temporal del negocio.", "Casos graves de estafa o abuso: Cierre definitivo del local y sanciones al propietario."]}]}, {"id": "dep-C-7", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 2: Normas de Operacion", "num": "7", "titulo": "Seguridad y Protección", "tag": "", "intro": ["Los dueños de negocios y locales civiles son responsables de la seguridad dentro de su propiedad."], "subs": [{"n": "7.1", "t": "Medidas de Seguridad", "l": ["Los dueños pueden contratar seguridad privada siempre que sea roleada de forma coherente.", "Se recomienda implementar medidas de seguridad realistas (cámaras, alarmas, cerraduras, etc.).", "La seguridad privada debe actuar dentro de los límites de la ley y las normas del servidor."]}, {"n": "7.2", "t": "En Caso de Robo o Incidente", "l": ["En caso de robo o incidente delictivo, se debe notificar inmediatamente a la Policía.", "El propietario debe rolear la denuncia y cooperar con las autoridades.", "Se debe guardar evidencia RP (grabaciones, testigos, etc.) para facilitar la investigación."]}]}, {"id": "dep-C-8", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 3: Prohibiciones", "num": "8", "titulo": "Prohibiciones Generales", "tag": "", "intro": ["Los negocios y locales civiles deben cumplir con las siguientes prohibiciones generales:"], "subs": [{"n": "8.1", "t": "Prohibiciones", "l": ["Operar negocios ilegales o de carácter inmoral sin aprobación expresa del Staff.", "Realizar estafas, fraudes o prácticas abusivas contra otros jugadores.", "Usar el negocio como fachada para actividades delictivas sin justificación RP.", "Permitir o fomentar el roleplay tóxico, discriminación o acoso dentro del local.", "Abandonar el negocio por períodos prolongados sin justificación.", "Cobrar precios excesivos o irrealistas que rompan la inmersión económica."]}, {"n": "8.2", "t": "Sanciones", "l": ["Falta leve: Amonestación y corrección inmediata.", "Falta media: Suspensión temporal del negocio.", "Falta grave o reiterada: Cierre definitivo del local y posibles sanciones al propietario."]}]}, {"id": "dep-C-9", "sec": "dep", "bloque": "C", "bloqueT": "Negocios y Locales Civiles", "cap": "Capítulo 4: Sanciones", "num": "9", "titulo": "Sanciones", "tag": "", "intro": ["El incumplimiento de las normas establecidas para negocios y locales civiles será sancionado según la gravedad de la falta."], "subs": [{"n": "9.1", "t": "Tipos de Sanciones", "l": ["Las sanciones podrán incluir, de menor a mayor gravedad:", "Advertencia verbal o escrita.", "Multa económica IC.", "Cierre temporal del negocio.", "Cierre definitivo del local y posible sanción al propietario."]}, {"n": "9.2", "t": "Aplicación de Sanciones", "l": ["La sanción se determinará según la gravedad, reiteración y el impacto causado a otros jugadores.", "El Staff evaluará cada caso de forma individual."]}, {"n": "9.3", "t": "Notificación", "l": ["Todas las sanciones serán notificadas por escrito al propietario del negocio. El propietario podrá apelar la sanción siguiendo el procedimiento establecido en el sistema de apelaciones."]}]}, {"id": "del-1", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "1", "titulo": "Permiso condicionado y calidad obligatoria para rol delictivo", "tag": "", "intro": ["El rol delictivo es una modalidad de juego que requiere permiso y un alto estándar de calidad."], "subs": [{"n": "1.1", "t": "Definición", "l": ["El rol delictivo abarca todas las actividades ilegales (robos, narco, pandillas, etc.). Solo pueden realizarlo jugadores que cumplan con los requisitos establecidos por la administración."]}, {"n": "1.2", "t": "Requisitos Obligatorios", "l": ["Contar con permiso condicionado otorgado por el Staff.", "Demostrar calidad y madurez en el roleplay previo como civil.", "Tener un backstory coherente y bien desarrollado para el personaje delictivo.", "Mantener un rol de alta calidad, con planificación, respeto a las normas y buena interacción."]}, {"n": "1.3", "t": "Principios Generales", "l": ["El rol delictivo no es un permiso para hacer lo que se quiera.", "Debe realizarse con responsabilidad, inmersión y respeto a las demás personas del servidor.", "La calidad del roleplay es obligatoria."]}, {"n": "1.4", "t": "Sanciones", "l": ["Incumplir los estándares de calidad o las condiciones del permiso es una falta grave. El Staff puede revocar el permiso en cualquier momento y aplicar sanciones que van desde amonestación hasta expulsión temporal o definitiva."]}]}, {"id": "del-2", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "2", "titulo": "Prohibición absoluta de delitos graves", "tag": "Prohibido estrictamente", "intro": ["Ciertos delitos se encuentran estrictamente prohibidos en el servidor, incluso dentro del rol delictivo."], "subs": [{"n": "2.1", "t": "Definición", "l": ["Se consideran delitos graves aquellas acciones que van en contra de las normas básicas de convivencia, inmersión y respeto del servidor."]}, {"n": "2.2", "t": "Delitos Prohibidos", "l": ["Violaciones o cualquier contenido de índole sexual no consentido.", "Tortura extrema o roleo excesivamente gore.", "Asesinatos masivos indiscriminados (Mass Killing).", "Secuestros prolongados sin motivo RP válido y sin dar oportunidad de interacción.", "Cualquier acto que implique pedofilia, racismo, homofobia o discriminación grave.", "Terrorismo o atentados que afecten masivamente al servidor."]}, {"n": "2.3", "t": "Principios Generales", "l": ["El rol delictivo debe ser divertido e inmersivo, pero nunca cruzar límites que afecten la experiencia de otros jugadores o la integridad de la comunidad.", "La calidad y el respeto siempre están por encima de la intensidad del rol."]}, {"n": "2.4", "t": "Sanciones", "l": ["La realización de cualquier delito grave es una falta extremadamente grave. La sanción habitual es la expulsión permanente del servidor y Discord, sin derecho a apelación."]}]}, {"id": "del-3", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "3", "titulo": "Registro De organizaciones criminales", "tag": "Obligatorio", "intro": ["Todas las organizaciones criminales deben estar debidamente registradas ante la administración del servidor."], "subs": [{"n": "3.1", "t": "Definición", "l": ["Una organización criminal es un grupo estructurado de jugadores que realiza actividades delictivas de forma regular (pandillas, carteles, mafias, etc.)."]}, {"n": "3.2", "t": "Requisitos de Registro", "l": ["Toda organización criminal debe presentar una solicitud formal al Staff mediante ticket con el siguiente formato:", "Solicitud de Registro de Organización Criminal", "Nombre de la Organización:", "Nombre del Líder Principal:", "Usuario de Roblox del Líder:", "Usuario de Discord del Líder:", "Número de Miembros Actuales:", "Backstory / Historia de la Organización:", "Tipo de Actividades Principales:", "Motivo por el que desean crear la organización:"]}, {"n": "3.3", "t": "Obligaciones", "l": ["Mantener un roleplay de calidad y coherente.", "Actualizar la información de la organización cuando haya cambios importantes.", "Respetar todas las normas de rol delictivo."]}, {"n": "3.4", "t": "Prohibiciones", "l": ["Operar una organización criminal sin registro oficial.", "Usar nombres ofensivos o que hagan referencia a grupos reales prohibidos.", "Reclutamiento masivo sin control de calidad."]}, {"n": "3.5", "t": "Sanciones", "l": ["Operar sin registro o incumplir las normas es una falta grave. Las sanciones pueden incluir la disolución del grupo y sanciones a sus miembros."]}]}, {"id": "del-4", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "4", "titulo": "Límite simultáneo de organizaciones", "tag": "", "intro": ["Se establece un límite máximo de organizaciones criminales activas para mantener el orden y la calidad del roleplay delictivo."], "subs": [{"n": "4.1", "t": "Definición", "l": ["El límite simultáneo se refiere al número máximo de organizaciones criminales que pueden estar operativas al mismo tiempo en el servidor."]}, {"n": "4.2", "t": "Límite Establecido", "l": ["Solo se permitirá un máximo de X organizaciones criminales activas simultáneamente (el número exacto será definido por la administración según el tamaño del servidor).", "Una vez alcanzado el límite, las nuevas solicitudes quedarán en lista de espera hasta que se libere un espacio.", "Cada organización debe mantener un mínimo de actividad para no ser disuelta."]}, {"n": "4.3", "t": "Restricciones por Jugador", "l": ["Un jugador solo puede pertenecer a una (1) organización criminal al mismo tiempo.", "No se permite formar parte de varias organizaciones criminales simultáneamente."]}, {"n": "4.4", "t": "Principios Generales", "l": ["El límite busca evitar saturación del rol delictivo y promover calidad en lugar de cantidad.", "Las organizaciones deben competir de forma justa y realista dentro del servidor."]}, {"n": "4.5", "t": "Sanciones", "l": ["Pertenecer a más de una organización criminal es una falta grave.", "Crear o intentar operar una organización sin cumplir el límite establecido puede resultar en disolución inmediata y sanciones a sus miembros."]}]}, {"id": "del-5", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "5", "titulo": "Requisitos mínimos para robos a tiendas y comercios", "tag": "Obligatorio", "intro": ["Los robos a tiendas y comercios deben cumplir con requisitos mínimos para garantizar calidad y realismo. (+20 Puntos por robo exitoso)"], "subs": [{"n": "5.1", "t": "Requisitos Obligatorios", "l": ["Mínimo 2 personas para realizar el robo (incluyendo conductor).", "Deben utilizar máscaras o elementos que oculten la identidad (Opcional).", "Se debe rolear la planificación y preparación previa del robo.", "Es obligatorio dar interacción verbal a los civiles presentes (amenazas, órdenes, etc.).", "Debe usarse el comando /me para describir acciones importantes.", "Entre un robo y otro, ya sea al mismo jugador o en la misma zona, deberá existir un lapso mínimo de 15 minutos fuera de rol (OOC)."]}, {"n": "5.2", "t": "Reglas Durante el Robo", "l": ["No se permite robar en menos de 4-5 minutos de interacción real.", "Deben respetar el FearRP de los civiles y empleados.", "Solo se permite llevar armas blancas o de fuego pequeñas (pistolas). Rifles o armas largas están prohibidos en robos a comercios pequeños.", "Se debe huir de forma realista una vez activada la alarma o llegada de la policía.", "Maximo de botin de: 4,000$"]}, {"n": "5.3", "t": "Prohibiciones", "l": ["Robar solo (solo raiding).", "Robar sin interacción con los civiles.", "Usar vehículos o armas demasiado llamativas o irrealistas.", "Matar o herir gravemente sin motivo justificado.", "Negociar mas dinero con la policia dinero (Se sobre entiende que el dinero que robas es del cajero)"]}, {"n": "5.4", "t": "Principios Generales", "l": ["Los robos deben ser roleados con planificación, tensión e inmersión.", "El objetivo es crear una escena divertida y realista para todos los involucrados."]}, {"n": "5.5", "t": "Sanciones", "l": ["Incumplir los requisitos mínimos se considera FailRP. Las sanciones pueden ir desde una advertencia hasta expulsión temporal, dependiendo de la gravedad y reiteración."]}]}, {"id": "del-6", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "6", "titulo": "Protocolo para atracos a entidades financieras", "tag": "Obligatorio", "intro": ["Los atracos a bancos y entidades financieras son operaciones de alto riesgo que requieren un protocolo estricto. (+100 Puntos por robo exitoso)"], "subs": [{"n": "6.1", "t": "Requisitos Mínimos", "l": ["Mínimo 4 personas participando activamente en el atraco.", "Debe existir una planificación previa y clara (reuniones IC).", "Todos los participantes deben usar máscaras o elementos que oculten su identidad.", "Es obligatorio contar con al menos un conductor y un vigilante."]}, {"n": "6.2", "t": "Durante el Atraco", "l": ["Se debe dar interacción clara y prolongada a los rehenes y empleados.", "El tiempo mínimo de roleo dentro de la entidad es de 8 minutos.", "Solo se permite el uso de armas acordes al rol (no se permiten armas excesivamente pesadas sin justificación).", "Debe rolearse el uso de herramientas (c4, taladros, etc.) de forma realista. (Obtenidas mediante roles IC anteriores)", "Se debe respetar el FearRP de todos los civiles involucrados."]}, {"n": "6.3", "t": "Prohibiciones", "l": ["Atracar con menos de 4 personas o sin planificación.", "Matar rehenes o empleados sin una razón RP extrema y justificada.", "Usar vehículos o armas irrealistas.", "Salir corriendo inmediatamente después de obtener el dinero sin roleo adecuado.", "Negociar mas dinero con la policia dinero (Se sobre entiende que el dinero que robas es de la boveda)"]}, {"n": "6.4", "t": "Principios Generales", "l": ["Los atracos a entidades financieras son eventos de alto nivel que deben ofrecer una experiencia inmersiva tanto para los delincuentes como para las víctimas y la policía.", "La calidad del roleplay es más importante que el botín obtenido.", "Botín maximo de: 40.000$", "Maximo de robos al banco cada 6 Dias"]}, {"n": "6.5", "t": "Sanciones", "l": ["Incumplir el protocolo es una falta grave.", "Las sanciones pueden ir desde amonestación hasta expulsión temporal o definitiva del servidor, especialmente si se genera FailRP o RDM."]}]}, {"id": "del-7", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "7", "titulo": "Condiciones para tiroteos masivos y guerras", "tag": "Obligatorio", "intro": ["Los tiroteos masivos y las guerras entre organizaciones son eventos de alto riesgo que requieren condiciones estrictas."], "subs": [{"n": "7.1", "t": "Definición", "l": ["Se consideran tiroteos masivos o guerras cualquier confrontación armada que involucre a más de 6 personas o se extienda por un período prolongado."]}, {"n": "7.2", "t": "Condiciones Obligatorias", "l": ["Debe existir una razón RP fuerte y previa (traición, disputa territorial, venganza justificada, etc.).", "Ambas partes deben haber tenido interacción RP significativa antes del conflicto.", "Se debe notificar al Staff con antelación cuando se planee un tiroteo masivo o guerra.", "Todos los participantes deben respetar el FearRP y evitar el Powergaming.", "El uso de armas debe ser coherente con el lore y equipamiento de cada organización."]}, {"n": "7.3", "t": "Prohibiciones", "l": ["Iniciar tiroteos masivos o guerras sin motivo RP válido.", "Realizar \"war\" por rencores OOC o trivialidades.", "Usar vehículos o tácticas irrealistas durante el conflicto.", "Matar indiscriminadamente sin dar oportunidad de rendición o interacción."]}, {"n": "7.4", "t": "Principios Generales", "l": ["Las guerras y tiroteos masivos deben ser el resultado lógico de una historia RP bien construida.", "La calidad, el realismo y el respeto a los demás jugadores son prioritarios."]}, {"n": "7.5", "t": "Sanciones", "l": ["Incumplir las condiciones para tiroteos masivos y guerras es una falta muy grave. Las sanciones pueden incluir expulsión temporal o definitiva de los involucrados."]}]}, {"id": "del-8", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "8", "titulo": "Condiciones para secuestros", "tag": "Obligatorio", "intro": ["Los secuestros son acciones de alto riesgo que deben cumplir estrictas condiciones de roleplay. (+60 Puntos por secuestro y negociaciones exitosas)"], "subs": [{"n": "8.1", "t": "Requisitos Mínimos", "l": ["Mínimo 2 personas participando en el secuestro (incluyendo conductor).", "Debe existir una razón RP válida y previa (deuda, venganza, información, rescate, etc.).", "El secuestrado debe recibir interacción constante y oportunidad de rolear.", "Se debe rolear el traslado y la retención del rehén de forma realista."]}, {"n": "8.2", "t": "Durante el Secuestro", "l": ["Tiempo mínimo de roleo: 10 minutos antes de cualquier exigencia o resolución.", "Se debe respetar el FearRP del rehén en todo momento.", "No se permite torturar o dañar gravemente al rehén sin motivo RP extremo y justificado.", "El secuestrado debe tener oportunidad de intentar escapar o negociar."]}, {"n": "8.3", "t": "Prohibiciones", "l": ["Secuestrar sin motivo RP válido o por simple diversión.", "Abandonar al rehén sin resolución RP.", "Usar el secuestro para hacer FailRP o Powergaming."]}, {"n": "8.4", "t": "Principios Generales", "l": ["El secuestro es una mecánica narrativa de alto impacto que debe beneficiar la historia de todos los involucrados.", "La calidad del roleplay y el respeto al FearRP son obligatorios."]}, {"n": "8.5", "t": "Sanciones", "l": ["Incumplir las condiciones para secuestros es una falta grave. Las sanciones pueden ir desde amonestación hasta expulsión temporal o definitiva."]}]}, {"id": "del-9", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "9", "titulo": "Uso de armas ilegales", "tag": "", "intro": ["El uso de armas ilegales está permitido únicamente bajo condiciones estrictas dentro del rol delictivo."], "subs": [{"n": "9.1", "t": "Definición", "l": ["Las armas ilegales son aquellas que no pueden ser adquiridas legalmente (fusiles de asalto, subfusiles, escopetas recortadas, etc.)."]}, {"n": "9.2", "t": "Requisitos para su Uso", "l": ["Solo pueden ser utilizadas por miembros de organizaciones criminales registradas.", "Deben tener una justificación RP coherente (defensa territorial, operaciones específicas, etc.).", "Su porte debe estar oculto o justificado según la situación.", "Solo se permite su uso en escenarios de alto riesgo con interacción RP previa.", "El arma larga debe mantenerse en el maletero del vehiculo mientras no este en uso."]}, {"n": "9.3", "t": "Prohibiciones", "l": ["Portar o usar armas ilegales como civil común sin pertenecer a una organización aprobada.", "Usarlas en robos a tiendas pequeñas o situaciones de bajo perfil.", "Mostrar armas ilegales de forma abierta en zonas públicas sin motivo RP.", "Usarlas para RDM, FailRP o intimidación gratuita."]}, {"n": "9.4", "t": "Principios Generales", "l": ["El uso de armas ilegales debe ser una decisión estratégica y coherente con el rol delictivo.", "Su empleo debe contribuir a crear escenas de calidad y tensión realista."]}, {"n": "9.5", "t": "Sanciones", "l": ["El uso indebido de armas ilegales es una falta grave. Las sanciones pueden ir desde confiscación permanente hasta expulsión temporal o definitiva del servidor."]}]}, {"id": "del-10", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "10", "titulo": "Puntos de producción y distribución en narcotráfico", "tag": "Importante", "intro": ["El narcotráfico es una actividad delictiva que requiere control y realismo en sus puntos de producción y distribución."], "subs": [{"n": "10.1", "t": "Definición", "l": ["Los puntos de producción y distribución son ubicaciones donde se cultiva, procesa, almacena o vende droga dentro del roleplay."]}, {"n": "10.2", "t": "Requisitos", "l": ["Todos los puntos de producción y distribución deben ser aprobados previamente por el Staff.", "Deben contar con una justificación RP coherente y backstory del lugar.", "Solo organizaciones criminales registradas pueden operar estos puntos.", "Se debe mantener roleplay activo y realista en dichas ubicaciones."]}, {"n": "10.3", "t": "Prohibiciones", "l": ["Crear o usar puntos de producción/distribución sin aprobación del Staff.", "Operar en zonas públicas o cercanas a áreas seguras.", "Usar estos puntos para hacer FailRP o Powergaming.", "Realizar ventas masivas o poco realistas sin interacción adecuada."]}, {"n": "10.4", "t": "Principios Generales", "l": ["El narcotráfico debe ser roleado con planificación, riesgo y consecuencias realistas.", "Se utilizaran objetos como envases de aceite para referenciar como punto de produccion.", "La calidad del roleplay es más importante que la cantidad de producto."]}, {"n": "10.5", "t": "Sanciones", "l": ["Incumplir las normas de puntos de producción y distribución es una falta grave. Las sanciones pueden incluir la destrucción del punto, confiscación y sanciones a los miembros de la organización."]}]}, {"id": "del-11", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "11", "titulo": "Territorios reclamados", "tag": "Importante", "intro": ["Los territorios reclamados son zonas controladas por organizaciones criminales para desarrollar sus actividades."], "subs": [{"n": "11.1", "t": "Definición", "l": ["Un territorio reclamado es un área específica del mapa que una organización declara como suya y en la que ejerce control RP."]}, {"n": "11.2", "t": "Requisitos para Reclamar", "l": ["Solo organizaciones criminales registradas pueden reclamar territorios.", "Debe presentarse una solicitud formal al Staff con justificación RP.", "El territorio debe tener un backstory coherente y ser defendible.", "Solo se permite reclamar un máximo de 1 territorio por organización."]}, {"n": "11.3", "t": "Reglas de Control", "l": ["Se debe mantener presencia y actividad RP constante en el territorio.", "Otras organizaciones pueden desafiar el control mediante conflictos RP justificados.", "Está permitido cobrar \"impuestos\" o proteger negocios dentro del territorio de forma realista.", "Las disputas territoriales deben notificarse al Staff."]}, {"n": "11.4", "t": "Prohibiciones", "l": ["Reclamar territorios sin aprobación del Staff.", "Reclamar zonas seguras, hospitales, comisarías o áreas gubernamentales.", "Usar el territorio para hacer FailRP o RDM constante.", "Abandonar un territorio sin notificar y justificar RP."]}, {"n": "11.5", "t": "Sanciones", "l": ["Incumplir las normas de territorios reclamados es una falta grave.", "Las sanciones pueden incluir la pérdida del territorio y sanciones a los miembros de la organización."]}]}, {"id": "del-12", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "12", "titulo": "Territorios reclamados", "tag": "Prohibido", "intro": ["El CK (muerte permanente) por deudas, traiciones o venganzas solo se permite tras:", "Rol previo mínimo de 3 interacciones significativas", "Advertencias claras y escaladas", "Justificación narrativa fuerte"], "subs": []}, {"id": "del-13", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "13", "titulo": "sicariatos y asesinatos", "tag": "Importante", "intro": ["Todo sicariato requiere:", "Encargo IC documentado (mensaje, llamada grabada)", "Pago previo o acordado", "Rol de vigilancia, seguimiento y ejecución", "Evidencia mínima para que sea investigable"], "subs": []}, {"id": "del-14", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "14", "titulo": "Lavado de dinero exclusivamente mediante negocios legales", "tag": "Considera", "intro": ["El lavado de dinero solo podrá realizarse a través de negocios legales registrados."], "subs": [{"n": "14.1", "t": "Definición", "l": ["El lavado de dinero es el proceso mediante el cual se integra dinero obtenido de actividades ilegales al sistema económico legal."]}, {"n": "14.2", "t": "Requisitos Obligatorios", "l": ["El lavado de dinero solo se permite a través de negocios legales registrados (empresas, tiendas, restaurantes, etc.).", "La organización debe poseer o tener acuerdo RP con el negocio utilizado.", "Se debe rolear el proceso de forma realista y progresiva (inversiones, compras, ventas, etc.).", "El Staff puede solicitar pruebas del proceso de lavado en cualquier momento."]}, {"n": "14.3", "t": "Prohibiciones", "l": ["Lavar dinero mediante métodos irrealistas o sin base en un negocio legal.", "Usar civiles ajenos o negocios sin su consentimiento RP.", "Lavar grandes cantidades de dinero de forma rápida y sin justificación.", "Usar el lavado de dinero para justificar FailRP o Powergaming."]}, {"n": "14.4", "t": "Principios Generales", "l": ["El lavado de dinero debe ser una actividad estratégica y de alto riesgo que forme parte de la historia de la organización.", "La calidad y el realismo son más importantes que la velocidad del proceso."]}, {"n": "14.5", "t": "Sanciones", "l": ["Incumplir las normas de lavado de dinero es una falta grave. Las sanciones pueden incluir la confiscación de bienes, pérdida de dinero y sanciones disciplinarias a los involucrados."]}]}, {"id": "del-15", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "15", "titulo": "Protección limitada a personal EMS", "tag": "Importante", "intro": ["Está prohibido atacar, secuestrar o matar a paramédicos EMS mientras:", "Estén en servicio activo (uniforme, luces encendidas)", "Atendiendo heridos Excepción: flagrancia extrema (EMS colaborando con criminales)"], "subs": []}, {"id": "del-16", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "16", "titulo": "Declaración para guerras entre bandas", "tag": "Obligatorio", "intro": ["Toda guerra entre organizaciones debe anunciarse públicamente IC (entorno) con:", "Motivo claro", "Zonas afectadas", "Duración aproximada Máximo 12 participantes por bando en enfrentamientos principales"], "subs": []}, {"id": "del-17", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "17", "titulo": "Requisitos elevados para robos a furgones blindados y convoyes", "tag": "Considera", "intro": ["Los robos a furgones blindados y convoyes son operaciones de alto nivel que requieren requisitos elevados. (+80 Puntos por robo exitoso)"], "subs": [{"n": "17.1", "t": "Requisitos Mínimos", "l": ["Mínimo 5 personas participando activamente.", "Debe existir una planificación previa detallada y notificada al Staff.", "Todos los participantes deben contar con roles definidos (conductor, francotirador, asaltantes, etc.).", "Se requiere equipamiento adecuado (armas de mayor calibre, explosivos, vehículos de escape, etc.)."]}, {"n": "17.2", "t": "Durante el Robo", "l": ["Tiempo mínimo de roleo: 12 minutos de interacción intensa.", "Se debe respetar el FearRP de guardias y civiles.", "La huida debe ser roleada de forma realista y estratégica.", "Está permitido el uso de armas más potentes debido a la naturaleza del objetivo."]}, {"n": "17.3", "t": "Prohibiciones", "l": ["Realizar el robo con menos de 5 personas o sin planificación.", "Usar tácticas suicidas o irrealistas.", "Matar indiscriminadamente a guardias o civiles sin justificación extrema.", "Abandonar el roleo a mitad del evento."]}, {"n": "17.4", "t": "Principios Generales", "l": ["Los robos a furgones blindados y convoyes son eventos de máxima dificultad.", "La calidad del roleplay, la coordinación y el realismo deben ser prioritarios."]}, {"n": "17.5", "t": "Sanciones", "l": ["Incumplir los requisitos elevados es una falta muy grave. Las sanciones pueden ir desde amonestación hasta expulsión temporal o definitiva de los involucrados."]}]}, {"id": "del-18", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "18", "titulo": "Base roleable por organización", "tag": "Importante", "intro": ["Toda banda o mafia debe poseer y mantener al menos una base física roleada:", "Casa, almacén, club nocturno, taller", "Visible y defendible IC", "Punto de reuniones, almacenamiento y planificación"], "subs": []}, {"id": "del-19", "sec": "del", "bloque": "", "bloqueT": "", "cap": "", "num": "19", "titulo": "NIVELES DE LOS GRUPOS", "tag": "Importante", "intro": ["Las organizaciones criminales se clasifican en tres niveles según su tamaño, influencia y capacidad operativa."], "subs": [{"n": "19.1", "t": "Nivel 0 - Delictivo Individual", "l": ["Descripción: Persona delictiva que trabaja por su cuenta.", "Actividades permitidas: Robos a tiendas, asaltos menores.", "Armas permitidas: Armas blancas, pistolas y revólveres."]}, {"n": "19.2", "t": "Nivel 1 - Pandilla (0-1400 Pts)", "l": ["Descripción: Grupos pequeños y locales con poca estructura.", "Máximo de miembros: 8", "Actividades permitidas: Robos a tiendas, asaltos menores, extorsión local.", "Armas permitidas: Armas blancas, pistolas y revólveres.", "Territorios: Solo 1 territorio pequeño."]}, {"n": "19.3", "t": "Nivel 2 - Banda (1400-3000 Pts)", "l": ["Descripción: Grupos medianos con mejor organización y presencia.", "Máximo de miembros: 15", "Actividades permitidas: Robos a comercios medianos, secuestros, venta de droga a mediana escala, asaltos a furgones blindados pequeños.", "Armas permitidas: Pistolas, subfusiles, escopetas.", "Territorios: Hasta 2 territorios medianos."]}, {"n": "19.4", "t": "Nivel 3 - Cartel (3000-MAX Pts)", "l": ["Descripción: Organizaciones grandes, altamente estructuradas y con gran influencia.", "Máximo de miembros: Sin límite (con aprobación del Staff)", "Actividades permitidas: Narcotráfico a gran escala, robos a entidades financieras, control territorial extenso, corrupción y lavado de dinero.", "Armas permitidas: Todo tipo de armamento (incluyendo rifles de asalto y armas pesadas con justificación RP).", "Territorios: Hasta 4 territorios grandes."]}, {"n": "19.5", "t": "Reglas Generales", "l": ["El nivel de la organización debe ser aprobado por el Staff.", "Los ascensos de nivel requieren demostración de calidad RP y actividad sostenida.", "Los líderes son responsables del cumplimiento de las normas por parte de todos sus miembros."]}, {"n": "19.6", "t": "Sanciones", "l": ["Incumplir las limitaciones según el nivel de la organización es una falta grave. Esto puede resultar en pérdida de nivel, disolución del grupo o sanciones a sus miembros."]}]}, {"id": "fin-1", "sec": "fin", "bloque": "", "bloqueT": "", "cap": "", "num": "1", "titulo": "Disposiciones Finales y Autoridad de la Normativa", "tag": "", "intro": ["Venezuela Community se reserva el derecho absoluto y exclusivo de establecer, interpretar, modificar y actualizar la presente Normativa en cualquier momento.", "Cualquier cambio o actualización será comunicado con antelación razonable a través de los canales oficiales de comunicaciones del servidor (principalmente anuncios en Discord, mensajes pinned o canales dedicados). La fecha de la última actualización aparecerá siempre al inicio de cada sección o documento para garantizar transparencia.", "El objetivo de estas modificaciones es mantener la integridad del roleplay, cerrar posibles vacíos interpretativos, corregir desequilibrios y prevenir cualquier intento de aprovechamiento o abuso por parte de los usuarios.", "Al ingresar a la comunidad y aceptar participar en el servidor (mediante verificación, lectura de reglas o uso continuado de los servicios), el usuario reconoce y acepta íntegramente la Normativa vigente en ese momento, así como su carácter vinculante y obligatorio. Esta aceptación implica que:", "No podrá invocar desconocimiento de las reglas.", "No podrá contradecir, cuestionar públicamente la validez o incumplir deliberadamente la Normativa.", "Acepta que cualquier violación será sancionada de acuerdo con los niveles establecidos (advertencia, kick, ban temporal, ban permanente, wipe de personaje, etc.), sin perjuicio de otras medidas que el equipo administrativo considere necesarias para proteger la comunidad.", "Las decisiones del equipo de moderación y administración son finales e inapelables en cuanto a la interpretación y aplicación de la Normativa, salvo el procedimiento de apelación expresamente previsto en las reglas correspondientes.", "Si en algún momento un usuario no está de acuerdo con la Normativa vigente o con alguna de sus actualizaciones, la única opción disponible es cesar inmediatamente su participación en la comunidad y retirarse del servidor de forma voluntaria. La permanencia implica aceptación plena y sin reservas de todas las disposiciones.", "Venezuela Community no es solo un servidor: es un espacio construido con esfuerzo colectivo. Respetar estas bases es la forma más directa de contribuir a que siga siendo un lugar de roleplay serio, justo y familiar para todos."], "subs": []}];
